package com.marketlens;

import com.marketlens.chart.ChartType;
import com.marketlens.chart.TimeFormat;
import com.marketlens.price.Timeframe;
import com.marketlens.ui.Palette;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(MarketLensConfig.GROUP)
public interface MarketLensConfig extends Config
{
	String GROUP = "marketlens";
	String CHART_TYPE_KEY = "chartType";
	String LAST_TIMEFRAME_KEY = "lastTimeframe";

	@ConfigItem(
		keyName = "defaultTimeframe",
		name = "Default timeframe",
		description = "Timeframe the price chart opens with",
		position = 1
	)
	default Timeframe defaultTimeframe()
	{
		return Timeframe.ONE_DAY;
	}

	@ConfigItem(
		keyName = "rememberTimeframe",
		name = "Remember last timeframe",
		description = "Open the chart with the timeframe you used last, instead of the default timeframe",
		position = 2
	)
	default boolean rememberTimeframe()
	{
		return false;
	}

	/** Last timeframe picked with the tabs; used instead of the default when {@link #rememberTimeframe()} is on. */
	@ConfigItem(
		keyName = LAST_TIMEFRAME_KEY,
		name = "",
		description = "",
		hidden = true
	)
	default Timeframe lastTimeframe()
	{
		return Timeframe.ONE_DAY;
	}

	@ConfigItem(
		keyName = CHART_TYPE_KEY,
		name = "Chart type",
		description = "Line or candlestick chart. Also changed, and remembered, with the buttons above the chart.",
		position = 3
	)
	default ChartType chartType()
	{
		return ChartType.LINE;
	}

	@ConfigItem(
		keyName = "buyColor",
		name = "Buy colour",
		description = "Colour of the buy price: its line, tag, volume bars, rising candles and positive profit",
		position = 4
	)
	default Color buyColor()
	{
		return new Color(Palette.BUY);
	}

	@ConfigItem(
		keyName = "sellColor",
		name = "Sell colour",
		description = "Colour of the sell price: its line, tag, volume bars, falling candles and negative profit",
		position = 5
	)
	default Color sellColor()
	{
		return new Color(Palette.SELL);
	}

	@ConfigItem(
		keyName = "showVolume",
		name = "Show volume bars",
		description = "Show the traded volume below the price chart",
		position = 6
	)
	default boolean showVolume()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOfferLine",
		name = "Show offer price line",
		description = "Show the price entered on the GE offer screen as a line on the chart",
		position = 7
	)
	default boolean showOfferLine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "crossCursor",
		name = "Cross cursor on chart",
		description = "Show a cross cursor while the mouse is over the chart",
		position = 8
	)
	default boolean crossCursor()
	{
		return true;
	}

	@ConfigItem(
		keyName = "snapCrosshairToCoins",
		name = "Snap crosshair to whole coins",
		description = "The crosshair's price line jumps from one whole coin to the next, as GE prices have no fractions."
			+ " Most visible on cheap items.",
		position = 9
	)
	default boolean snapCrosshairToCoins()
	{
		return true;
	}

	@ConfigItem(
		keyName = "timeFormat",
		name = "Time format",
		description = "12- or 24-hour clock on the chart. Automatic follows the language and region Java reports"
			+ " for this computer.",
		position = 10
	)
	default TimeFormat timeFormat()
	{
		return TimeFormat.AUTOMATIC;
	}
}

package com.marketlens;

import com.google.inject.Provides;
import com.marketlens.ge.GeButtonInjector;
import com.marketlens.price.PriceService;
import com.marketlens.price.Timeframe;
import com.marketlens.ui.ChartCursor;
import com.marketlens.ui.ChartInput;
import com.marketlens.ui.ExpandedChartOverlay;
import com.marketlens.ui.ExpandedWindowInput;
import com.marketlens.ui.GeChartOverlay;
import com.marketlens.ui.MarketLensSprite;
import com.marketlens.ui.PriceWindow;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Market Lens",
	description = "Real-time Grand Exchange price charts, right inside the GE offer screen",
	tags = {"grand exchange", "ge", "price", "chart", "flipping", "wiki"}
)
public class MarketLensPlugin extends Plugin
{
	@Inject
	private ClientThread clientThread;
	@Inject
	private MarketLensConfig config;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private MouseManager mouseManager;
	@Inject
	private KeyManager keyManager;
	@Inject
	private PriceService priceService;
	@Inject
	private GeButtonInjector buttonInjector;
	@Inject
	private PriceWindow window;
	@Inject
	private GeChartOverlay chartOverlay;
	@Inject
	private ExpandedChartOverlay expandedChartOverlay;
	@Inject
	private ChartInput chartInput;
	@Inject
	private ExpandedWindowInput expandedWindowInput;
	@Inject
	private ChartCursor chartCursor;
	@Inject
	private SpriteManager spriteManager;

	@Override
	protected void startUp()
	{
		spriteManager.addSpriteOverrides(MarketLensSprite.values());
		buttonInjector.setOnClick(itemId -> window.open(itemId, openingTimeframe(), config.chartType()));
		// Start loading as soon as the user points at the button, so the data is usually ready by the click.
		buttonInjector.setOnHover(itemId -> priceService.refresh(itemId, openingTimeframe()));
		priceService.setOnUpdate(() -> clientThread.invokeLater(window::refresh));
		overlayManager.add(chartOverlay);
		overlayManager.add(expandedChartOverlay);
		// Chart first, so drags and clicks on the chart reach it before the window takes the rest.
		mouseManager.registerMouseListener(chartInput);
		mouseManager.registerMouseListener(expandedWindowInput);
		mouseManager.registerMouseWheelListener(chartInput);
		keyManager.registerKeyListener(window);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(window);
		mouseManager.unregisterMouseWheelListener(chartInput);
		mouseManager.unregisterMouseListener(expandedWindowInput);
		mouseManager.unregisterMouseListener(chartInput);
		chartCursor.update(false);
		overlayManager.remove(expandedChartOverlay);
		overlayManager.remove(chartOverlay);
		priceService.setOnUpdate(() -> {});
		priceService.clear();
		clientThread.invoke(() ->
		{
			buttonInjector.reset();
			window.close();
		});
		spriteManager.removeSpriteOverrides(MarketLensSprite.values());
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		buttonInjector.update();
		window.ensureAttached();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		window.onGameTick();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (MarketLensConfig.GROUP.equals(event.getGroup()))
		{
			// The chart reads the config every frame; the window's price texts need a refresh for new colours.
			clientThread.invoke(window::refresh);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.GE_OFFERS)
		{
			window.close();
			buttonInjector.reset();
		}
	}

	private Timeframe openingTimeframe()
	{
		return config.rememberTimeframe() ? config.lastTimeframe() : config.defaultTimeframe();
	}

	@Provides
	MarketLensConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MarketLensConfig.class);
	}
}

package com.marketlens.chart;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/** "Nice" tick positions and labels for the price and time axes. */
public final class AxisTicks
{
	private static final long MINUTE = 60;
	private static final long HOUR = 60 * MINUTE;
	private static final long DAY = 24 * HOUR;
	private static final long[] TIME_STEPS = {
		5 * MINUTE, 10 * MINUTE, 15 * MINUTE, 30 * MINUTE,
		HOUR, 2 * HOUR, 3 * HOUR, 6 * HOUR, 12 * HOUR,
		DAY, 2 * DAY, 7 * DAY, 14 * DAY, 30 * DAY, 61 * DAY, 91 * DAY, 182 * DAY,
	};

	private static final DateTimeFormatter CLOCK_24H = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter CLOCK_12H = DateTimeFormatter.ofPattern("h:mm a", Locale.ENGLISH);
	private static final DateTimeFormatter DAY_MONTH = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter MONTH_YEAR = DateTimeFormatter.ofPattern("MMM ''yy", Locale.ENGLISH);
	private static final DateTimeFormatter CROSSHAIR_INTRADAY_24H = DateTimeFormatter.ofPattern("EEE d MMM HH:mm", Locale.ENGLISH);
	private static final DateTimeFormatter CROSSHAIR_INTRADAY_12H = DateTimeFormatter.ofPattern("EEE d MMM h:mm a", Locale.ENGLISH);
	private static final DateTimeFormatter CROSSHAIR_DAILY = DateTimeFormatter.ofPattern("EEE d MMM ''yy", Locale.ENGLISH);

	private AxisTicks()
	{
	}

	/** Round price levels (1, 2, 2.5 or 5 x 10^n, at least 1gp apart) inside [min, max]. */
	public static List<Double> prices(double min, double max, int targetCount)
	{
		List<Double> ticks = new ArrayList<>();
		if (!(max > min) || targetCount < 1)
		{
			return ticks;
		}

		double raw = (max - min) / targetCount;
		double magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
		double norm = raw / magnitude;
		double nice = norm < 1.5 ? 1 : norm < 2.25 ? 2 : norm < 3.5 ? 2.5 : norm < 7 ? 5 : 10;
		if (nice == 2.5 && magnitude < 10)
		{
			// 2.5gp steps would give fractional coin labels
			nice = 2;
		}
		double step = Math.max(1, nice * magnitude);

		double first = Math.ceil(min / step) * step;
		for (int i = 0; first + i * step <= max; i++)
		{
			ticks.add(first + i * step);
		}
		return ticks;
	}

	/** Smallest step from {@link #TIME_STEPS} that yields at most {@code targetCount} ticks. */
	public static long timeStep(double start, double end, int targetCount)
	{
		double span = end - start;
		for (long step : TIME_STEPS)
		{
			if (span / step <= targetCount)
			{
				return step;
			}
		}
		return TIME_STEPS[TIME_STEPS.length - 1];
	}

	/** Tick times aligned to local wall-clock multiples of {@code step}. */
	public static List<Long> times(double start, double end, long step, ZoneId zone)
	{
		List<Long> ticks = new ArrayList<>();
		if (!(end > start))
		{
			return ticks;
		}
		long offset = zone.getRules().getOffset(Instant.ofEpochSecond((long) start)).getTotalSeconds();
		long first = (long) Math.ceil((start + offset) / step) * step - offset;
		for (long t = first; t <= end; t += step)
		{
			ticks.add(t);
		}
		return ticks;
	}

	/** Axis label: clock time for intraday steps (date at midnight), day-month or month-year otherwise. */
	public static String timeLabel(long epochSeconds, long step, ZoneId zone, boolean twelveHour)
	{
		ZonedDateTime t = Instant.ofEpochSecond(epochSeconds).atZone(zone);
		if (step < DAY)
		{
			boolean midnight = t.getHour() == 0 && t.getMinute() == 0;
			return (midnight ? DAY_MONTH : twelveHour ? CLOCK_12H : CLOCK_24H).format(t);
		}
		return (step < 30 * DAY ? DAY_MONTH : MONTH_YEAR).format(t);
	}

	/** Full timestamp for the crosshair label. */
	public static String crosshairLabel(long epochSeconds, long bucketSeconds, ZoneId zone, boolean twelveHour)
	{
		ZonedDateTime t = Instant.ofEpochSecond(epochSeconds).atZone(zone);
		if (bucketSeconds >= DAY)
		{
			return CROSSHAIR_DAILY.format(t);
		}
		return (twelveHour ? CROSSHAIR_INTRADAY_12H : CROSSHAIR_INTRADAY_24H).format(t);
	}
}

package com.marketlens.chart;

import com.marketlens.price.TimeseriesPoint;
import lombok.Value;

/** One candlestick, built from the wiki's bucket averages (see {@link Candles}). */
@Value
public class Candle
{
	long timestamp;
	double open;
	double high;
	double low;
	double close;
	Long buyVolume;
	Long sellVolume;

	public boolean isUp()
	{
		return close >= open;
	}

	/** The candle as a chart point (high, low and volumes), so the scale and volume bars can use it unchanged. */
	public TimeseriesPoint asPoint()
	{
		return new TimeseriesPoint(timestamp, high, low, buyVolume, sellVolume);
	}
}

package com.marketlens.chart;

import com.marketlens.price.TimeseriesPoint;
import java.util.ArrayList;
import java.util.List;

/**
 * Builds candlesticks from the wiki's price buckets. The API has no open/close or single-trade highs and lows,
 * only each bucket's average instant-buy and instant-sell price, so a candle is built from those averages:
 * <ul>
 * <li>open: the previous candle's close (the first bucket's midpoint for the first candle)</li>
 * <li>close: the midpoint of the candle's last bucket that traded</li>
 * <li>high: the highest average instant-buy price in the candle; low: the lowest average instant-sell price
 * (widened to include open and close)</li>
 * </ul>
 * Buckets are grouped by fixed clock boundaries of {@code intervalSeconds}, like {@link Downsample}.
 */
public final class Candles
{
	private Candles()
	{
	}

	public static List<Candle> build(List<TimeseriesPoint> points, long intervalSeconds)
	{
		List<Candle> candles = new ArrayList<>();
		Double previousClose = null;
		Group group = null;
		for (TimeseriesPoint point : points)
		{
			long start = Math.floorDiv(point.getTimestamp(), intervalSeconds) * intervalSeconds;
			if (group == null || group.start != start)
			{
				previousClose = finish(group, previousClose, candles);
				group = new Group(start);
			}
			group.add(point);
		}
		finish(group, previousClose, candles);
		return candles;
	}

	/** Adds the group's candle, if it traded at all, and returns the close to open the next candle with. */
	private static Double finish(Group group, Double previousClose, List<Candle> candles)
	{
		if (group == null || group.lastMid == null)
		{
			return previousClose;
		}
		double open = previousClose != null ? previousClose : group.firstMid;
		double close = group.lastMid;
		double high = Math.max(Math.max(open, close), group.high);
		double low = Math.min(Math.min(open, close), group.low);
		candles.add(new Candle(group.start, open, high, low, close, group.buyVolume, group.sellVolume));
		return close;
	}

	private static final class Group
	{
		private final long start;
		private Double firstMid;
		private Double lastMid;
		private double high = -Double.MAX_VALUE;
		private double low = Double.MAX_VALUE;
		private Long buyVolume;
		private Long sellVolume;

		Group(long start)
		{
			this.start = start;
		}

		void add(TimeseriesPoint p)
		{
			Double buy = p.getAvgHighPrice();
			Double sell = p.getAvgLowPrice();
			if (buy != null)
			{
				high = Math.max(high, buy);
				low = Math.min(low, buy);
			}
			if (sell != null)
			{
				high = Math.max(high, sell);
				low = Math.min(low, sell);
			}
			Double mid = buy;
			if (buy != null && sell != null)
			{
				mid = (buy + sell) / 2;
			}
			else if (buy == null)
			{
				mid = sell;
			}
			if (mid != null)
			{
				if (firstMid == null)
				{
					firstMid = mid;
				}
				lastMid = mid;
			}
			buyVolume = add(buyVolume, p.getHighPriceVolume());
			sellVolume = add(sellVolume, p.getLowPriceVolume());
		}

		private static Long add(Long total, Long volume)
		{
			return volume == null ? total : (total == null ? 0 : total) + volume;
		}
	}
}

package com.marketlens.chart;

import com.marketlens.price.TimeseriesPoint;
import java.awt.Rectangle;
import java.util.List;
import lombok.Getter;

/**
 * Geometry of one chart frame: which points are visible, the price range, the price and volume panes,
 * and the mapping between time/price and pixels. Pure maths, so it can be tested without a client.
 */
public final class ChartScale
{
	private static final double VOLUME_FRACTION = 0.2;
	private static final int PANE_GAP = 4;
	/** Room above and below the highest and lowest price, as a fraction of the range. */
	private static final double PRICE_PADDING = 0.08;

	private final List<TimeseriesPoint> points;
	private final double start;
	private final double end;
	private final long bucketSeconds;
	@Getter
	private final Rectangle plot;
	@Getter
	private final Rectangle pricePane;
	@Getter
	private final Rectangle volumePane;
	/** First and last visible point, with one point of slack either side so lines run to the edges. */
	@Getter
	private final int first;
	@Getter
	private final int last;
	@Getter
	private final double min;
	@Getter
	private final double max;
	@Getter
	private final long maxVolume;

	/**
	 * @param points     the series, oldest first; not empty
	 * @param start      visible window start, epoch seconds
	 * @param end        visible window end, epoch seconds
	 * @param withVolume whether to keep a volume pane below the prices; without it the prices use the full height
	 * @param livePrices current prices to fit on the scale when the newest point is visible (nulls ignored)
	 */
	public ChartScale(List<TimeseriesPoint> points, double start, double end, long bucketSeconds, Rectangle plot,
		boolean withVolume, Double... livePrices)
	{
		this.points = points;
		this.start = start;
		this.end = end;
		this.bucketSeconds = bucketSeconds;
		this.plot = plot;

		int volumeHeight = withVolume ? (int) (plot.height * VOLUME_FRACTION) : 0;
		int gap = withVolume ? PANE_GAP : 0;
		pricePane = new Rectangle(plot.x, plot.y, plot.width, plot.height - volumeHeight - gap);
		volumePane = new Rectangle(plot.x, plot.y + plot.height - volumeHeight, plot.width, volumeHeight);

		int lo = 0;
		while (lo < points.size() - 1 && points.get(lo + 1).getTimestamp() < start)
		{
			lo++;
		}
		int hi = points.size() - 1;
		while (hi > lo && points.get(hi - 1).getTimestamp() > end)
		{
			hi--;
		}
		first = lo;
		last = hi;

		Range range = new Range();
		long volume = 1;
		for (int i = first; i <= last; i++)
		{
			TimeseriesPoint p = points.get(i);
			range.include(p.getAvgHighPrice());
			range.include(p.getAvgLowPrice());
			volume = Math.max(volume, p.totalVolume());
		}
		// When the newest data is in view, fit the live prices too, so their tags never fall off the scale.
		if (last == points.size() - 1)
		{
			for (Double price : livePrices)
			{
				range.include(price);
			}
		}
		if (range.min > range.max)
		{
			range.min = 0;
			range.max = 1;
		}
		double pad = Math.max(1, (range.max - range.min) * PRICE_PADDING);
		min = range.min - pad;
		max = range.max + pad;
		maxVolume = volume;
	}

	public int x(double time)
	{
		return plot.x + (int) Math.round((time - start) / (end - start) * plot.width);
	}

	public int y(double price)
	{
		return pricePane.y + (int) Math.round((max - price) / (max - min) * pricePane.height);
	}

	public double timeAt(int x)
	{
		return start + (double) (x - plot.x) / plot.width * (end - start);
	}

	public double priceAt(int y)
	{
		return max - (double) (y - pricePane.y) / pricePane.height * (max - min);
	}

	public double getStart()
	{
		return start;
	}

	public double getEnd()
	{
		return end;
	}

	/** Width of one bucket in pixels. */
	public double bucketWidth()
	{
		return plot.width * bucketSeconds / (end - start);
	}

	/** Bar height in the volume pane for {@code volume}, scaled to the largest visible volume. */
	public int volumeHeight(Long volume)
	{
		return volume == null ? 0 : (int) (volume * volumePane.height / maxVolume);
	}

	/** Index of the visible point closest to {@code time}. */
	public int nearestIndex(double time)
	{
		int best = first;
		for (int i = first + 1; i <= last; i++)
		{
			if (Math.abs(points.get(i).getTimestamp() - time) < Math.abs(points.get(best).getTimestamp() - time))
			{
				best = i;
			}
		}
		return best;
	}

	private static final class Range
	{
		private double min = Double.MAX_VALUE;
		private double max = -Double.MAX_VALUE;

		void include(Double price)
		{
			if (price != null)
			{
				min = Math.min(min, price);
				max = Math.max(max, price);
			}
		}
	}
}

package com.marketlens.chart;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** How the price series is drawn. */
@Getter
@RequiredArgsConstructor
public enum ChartType
{
	LINE("Line", "Linechart"),
	CANDLES("Candles", "Candlechart");

	private final String label;
	/** Name in the toggle button's menu option, e.g. "Show Linechart". */
	private final String menuName;

	@Override
	public String toString()
	{
		return label;
	}
}

package com.marketlens.chart;

/**
 * The visible time window of the chart, in epoch seconds. Pure maths, no rendering.
 * Mutated from the AWT thread (mouse input) and read from the client thread (rendering), hence synchronized.
 */
public final class ChartViewport
{
	private double dataStart;
	private double dataEnd;
	private double minSpan;
	private double initialWindow;
	private double start;
	private double end;

	/**
	 * Replaces the data range and resets the view.
	 *
	 * @param minSpan       smallest zoomable span (e.g. a few buckets)
	 * @param initialWindow span to show on reset, anchored to the end; 0 shows everything
	 */
	public synchronized void setData(long dataStart, long dataEnd, long minSpan, long initialWindow)
	{
		this.dataStart = dataStart;
		this.dataEnd = Math.max(dataEnd, dataStart + 1);
		this.minSpan = Math.max(1, Math.min(minSpan, this.dataEnd - dataStart));
		this.initialWindow = initialWindow;
		reset();
	}

	/**
	 * Replaces the data range after a refresh, keeping the user's zoom.
	 * If the view was showing the newest data it keeps following it.
	 */
	public synchronized void updateRange(long dataStart, long dataEnd)
	{
		boolean following = end >= this.dataEnd;
		double span = end - start;
		this.dataStart = dataStart;
		this.dataEnd = Math.max(dataEnd, dataStart + 1);
		span = Math.min(span, this.dataEnd - dataStart);
		if (following)
		{
			end = this.dataEnd;
			start = end - span;
		}
		keepInsideData();
	}

	public synchronized void reset()
	{
		double span = dataEnd - dataStart;
		double window = initialWindow > 0 ? Math.max(minSpan, Math.min(initialWindow, span)) : span;
		end = dataEnd;
		start = dataEnd - window;
	}

	/** Zooms around {@code anchor}, keeping it at the same screen position. factor &lt; 1 zooms in. */
	public synchronized void zoom(double factor, double anchor)
	{
		double span = end - start;
		double newSpan = clamp(span * factor, minSpan, dataEnd - dataStart);
		double ratio = span <= 0 ? 1 : clamp((anchor - start) / span, 0, 1);
		start = anchor - ratio * newSpan;
		end = start + newSpan;
		keepInsideData();
	}

	/** Shifts the window by {@code seconds}; positive moves towards newer data. */
	public synchronized void pan(double seconds)
	{
		start += seconds;
		end += seconds;
		keepInsideData();
	}

	public synchronized double getStart()
	{
		return start;
	}

	public synchronized double getEnd()
	{
		return end;
	}

	private void keepInsideData()
	{
		double span = end - start;
		if (start < dataStart)
		{
			start = dataStart;
			end = start + span;
		}
		if (end > dataEnd)
		{
			end = dataEnd;
			start = end - span;
		}
	}

	private static double clamp(double v, double min, double max)
	{
		return Math.max(min, Math.min(max, v));
	}
}

package com.marketlens.chart;

import com.marketlens.price.TimeseriesPoint;
import java.util.ArrayList;
import java.util.List;

/**
 * Merges price buckets into larger ones when they are too dense to read, without losing accuracy.
 * The wiki's bucket price is the average of the trades in that bucket, so the volume-weighted average of
 * several buckets is exactly the average price of all their trades together. Volumes are summed.
 * Groups are aligned to fixed clock boundaries, so they don't shift while the user pans.
 */
public final class Downsample
{
	private static final long MINUTE = 60;
	private static final long HOUR = 60 * MINUTE;
	private static final long DAY = 24 * HOUR;
	/** Intervals a series can be merged into, smallest first. */
	private static final long[] INTERVALS = {
		5 * MINUTE, 15 * MINUTE, 30 * MINUTE, HOUR, 2 * HOUR, 3 * HOUR, 6 * HOUR, 12 * HOUR,
		DAY, 2 * DAY, 3 * DAY, 7 * DAY, 14 * DAY, 28 * DAY,
	};

	private Downsample()
	{
	}

	/**
	 * The smallest interval, a whole multiple of {@code bucketSeconds}, at which points are at least
	 * {@code minPixels} apart. Returns {@code bucketSeconds} itself when the raw buckets are far enough apart.
	 */
	public static long interval(long bucketSeconds, double secondsPerPixel, double minPixels)
	{
		if (bucketSeconds / secondsPerPixel >= minPixels)
		{
			return bucketSeconds;
		}
		for (long interval : INTERVALS)
		{
			if (interval > bucketSeconds && interval % bucketSeconds == 0 && interval / secondsPerPixel >= minPixels)
			{
				return interval;
			}
		}
		return INTERVALS[INTERVALS.length - 1];
	}

	/** Merges {@code points} (oldest first) into buckets of {@code intervalSeconds}, aligned to multiples of it. */
	public static List<TimeseriesPoint> merge(List<TimeseriesPoint> points, long intervalSeconds)
	{
		List<TimeseriesPoint> merged = new ArrayList<>();
		Group group = null;
		for (TimeseriesPoint point : points)
		{
			long start = Math.floorDiv(point.getTimestamp(), intervalSeconds) * intervalSeconds;
			if (group == null || group.start != start)
			{
				if (group != null)
				{
					merged.add(group.toPoint());
				}
				group = new Group(start);
			}
			group.add(point);
		}
		if (group != null)
		{
			merged.add(group.toPoint());
		}
		return merged;
	}

	/** Running totals for one merged bucket. */
	private static final class Group
	{
		private final long start;
		private final Side high = new Side();
		private final Side low = new Side();

		Group(long start)
		{
			this.start = start;
		}

		void add(TimeseriesPoint point)
		{
			high.add(point.getAvgHighPrice(), point.getHighPriceVolume());
			low.add(point.getAvgLowPrice(), point.getLowPriceVolume());
		}

		TimeseriesPoint toPoint()
		{
			return new TimeseriesPoint(start, high.price(), low.price(), high.volume(), low.volume());
		}
	}

	/** One side (instant buys or instant sells) of a merged bucket. */
	private static final class Side
	{
		private double weightedSum;
		private long weight;
		private double plainSum;
		private int prices;
		private Long volume;

		void add(Double price, Long tradeVolume)
		{
			if (tradeVolume != null)
			{
				volume = (volume == null ? 0 : volume) + tradeVolume;
			}
			if (price == null)
			{
				return;
			}
			plainSum += price;
			prices++;
			if (tradeVolume != null && tradeVolume > 0)
			{
				weightedSum += price * tradeVolume;
				weight += tradeVolume;
			}
		}

		/** Volume-weighted average; a plain average only if no bucket reported its volume. */
		Double price()
		{
			if (weight > 0)
			{
				return weightedSum / weight;
			}
			return prices > 0 ? plainSum / prices : null;
		}

		Long volume()
		{
			return volume;
		}
	}
}

package com.marketlens.chart;

import java.util.Arrays;

/** Positions axis labels (like price tags) so they never overlap. */
public final class LabelLayout
{
	private LabelLayout()
	{
	}

	/**
	 * Moves label centres apart so labels of {@code height} px don't overlap, staying within [min, max].
	 * Labels keep their order; a label is only pushed down if it collides with the one above it,
	 * and the whole stack shifts up if that pushes it past {@code max}.
	 *
	 * @param centers desired vertical centres, any order
	 * @return adjusted centres, in the same order as {@code centers}
	 */
	public static int[] separate(int[] centers, int height, int min, int max)
	{
		Integer[] order = new Integer[centers.length];
		for (int i = 0; i < order.length; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (a, b) -> Integer.compare(centers[a], centers[b]));

		int[] result = centers.clone();
		int half = height / 2;
		for (int k = 0; k < order.length; k++)
		{
			int i = order[k];
			int lowest = k == 0 ? min + half : result[order[k - 1]] + height;
			result[i] = Math.max(result[i], lowest);
		}
		for (int k = order.length - 1; k >= 0; k--)
		{
			int i = order[k];
			int highest = k == order.length - 1 ? max - half : result[order[k + 1]] - height;
			result[i] = Math.min(result[i], highest);
		}
		return result;
	}
}

package com.marketlens.chart;

import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * Number and age formatting shared by the window and the chart. The chart formats labels every frame,
 * so formatters are created once per thread (DecimalFormat isn't thread-safe) and reused.
 */
public final class PriceFormat
{
	private static final DecimalFormatSymbols SYMBOLS = DecimalFormatSymbols.getInstance(Locale.ENGLISH);
	private static final ThreadLocal<DecimalFormat> GROUPED = ThreadLocal.withInitial(() -> format("#,##0"));
	/** Fixed-decimal formats for scaled axis labels, indexed by number of decimals. */
	private static final ThreadLocal<DecimalFormat[]> SCALED = ThreadLocal.withInitial(() -> new DecimalFormat[]{
		format("0"), format("0.0"), format("0.00"), format("0.000"),
	});

	private PriceFormat()
	{
	}

	/** 1712400 -> "1,712,400". */
	public static String exact(long value)
	{
		return GROUPED.get().format(value);
	}

	/** Signed variant for deltas: 14400 -> "+14,400", -34248 -> "-34,248". */
	public static String signed(long value)
	{
		return (value > 0 ? "+" : "") + exact(value);
	}

	/**
	 * Axis label with just enough decimals to tell ticks {@code step} apart:
	 * below 1M it is exact ("812,500"), above it is scaled ("1.705M" for a 5K step, "1.71M" for a 10K step).
	 */
	public static String axis(double value, double step)
	{
		double abs = Math.abs(value);
		if (abs < 1e6)
		{
			return exact(Math.round(value));
		}
		double unit = abs >= 1e9 ? 1e9 : 1e6;
		int decimals = (int) Math.max(0, Math.min(3, Math.ceil(-Math.log10(step / unit))));
		return SCALED.get()[decimals].format(value / unit) + (unit == 1e9 ? "B" : "M");
	}

	/** Seconds elapsed -> "just now", "4m ago", "3h ago", "2d ago". */
	public static String age(long seconds)
	{
		if (seconds < 60)
		{
			return "just now";
		}
		if (seconds < 3600)
		{
			return (seconds / 60) + "m ago";
		}
		if (seconds < 86400)
		{
			return (seconds / 3600) + "h ago";
		}
		return (seconds / 86400) + "d ago";
	}

	private static DecimalFormat format(String pattern)
	{
		DecimalFormat format = new DecimalFormat(pattern, SYMBOLS);
		format.setRoundingMode(RoundingMode.HALF_UP);
		return format;
	}
}

package com.marketlens.chart;

import java.time.chrono.IsoChronology;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.FormatStyle;
import java.util.Locale;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** 12- or 24-hour clock for the chart's time labels. */
@Getter
@RequiredArgsConstructor
public enum TimeFormat
{
	AUTOMATIC("Automatic"),
	TWELVE_HOUR("12-hour"),
	TWENTY_FOUR_HOUR("24-hour");

	/** Whether the default locale writes times with a 12-hour clock; looked up once. */
	private static final boolean LOCALE_TWELVE_HOUR = usesTwelveHour(Locale.getDefault(Locale.Category.FORMAT));

	private final String label;

	public boolean isTwelveHour()
	{
		return this == AUTOMATIC ? LOCALE_TWELVE_HOUR : this == TWELVE_HOUR;
	}

	/** True if the locale's short time pattern uses a 12-hour field, like "h:mm a" in the US. */
	static boolean usesTwelveHour(Locale locale)
	{
		String pattern = DateTimeFormatterBuilder.getLocalizedDateTimePattern(null, FormatStyle.SHORT,
			IsoChronology.INSTANCE, locale);
		return pattern.indexOf('h') >= 0 || pattern.indexOf('K') >= 0;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.marketlens.ge;

import com.marketlens.ui.GeWidgets;
import com.marketlens.ui.MarketLensSprite;
import java.awt.Rectangle;
import java.util.function.IntConsumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

/**
 * Keeps a Market Lens button on the GE offer setup screen, right of the Confirm button,
 * mirrored to the back arrow on the left: an icon-only small GE button with a price-chart icon.
 * The game rebuilds the setup widgets often, so {@link #update()} re-adds the button whenever it disappears.
 * Client thread only.
 */
@Slf4j
@Singleton
public class GeButtonInjector
{
	private static final String NAME = "Market Lens";
	private static final int MIN_GAP = 6;

	private final Client client;
	private final ItemManager itemManager;
	private final GeWidgets geWidgets;

	private Widget button;
	private IntConsumer onClick = id -> {};
	private IntConsumer onHover = id -> {};

	@Inject
	GeButtonInjector(Client client, ItemManager itemManager, GeWidgets geWidgets)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.geWidgets = geWidgets;
	}

	public void setOnClick(IntConsumer onClick)
	{
		this.onClick = onClick;
	}

	/** Called when the mouse moves onto the button; lets the plugin start loading prices before the click. */
	public void setOnHover(IntConsumer onHover)
	{
		this.onHover = onHover;
	}

	/** Cheap enough to run every client tick: does nothing while the button is in place. */
	public void update()
	{
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		Widget confirm = client.getWidget(InterfaceID.GeOffers.SETUP_CONFIRM);
		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (setup == null || setup.isHidden() || confirm == null || confirm.isHidden() || itemId <= 0)
		{
			hide();
			return;
		}

		Widget parent = confirm.getParent();
		if (button != null && parent.getChild(button.getIndex()) == button)
		{
			button.setHidden(false);
			return;
		}
		button = createButton(parent, confirm);
	}

	public void hide()
	{
		if (button != null)
		{
			button.setHidden(true);
		}
	}

	public void reset()
	{
		hide();
		button = null;
	}

	private Widget createButton(Widget parent, Widget confirm)
	{
		Rectangle c = confirm.getBounds();
		int confirmCenterX = c.x + c.width / 2;

		// Mirror the back arrow across the Confirm button: the right margin equals the arrow's left margin.
		Widget back = client.getWidget(InterfaceID.GeOffers.BACK);
		int right = back != null && !back.isHidden()
			? 2 * confirmCenterX - back.getBounds().x
			: c.x + c.width + GeWidgets.SMALL_BUTTON_SIZE + MIN_GAP;
		int left = Math.max(right - GeWidgets.SMALL_BUTTON_SIZE, c.x + c.width + MIN_GAP);

		Point origin = parent.getCanvasLocation();
		int x = left - origin.getX();
		int y = c.y + (c.height - GeWidgets.SMALL_BUTTON_SIZE) / 2 - origin.getY();

		log.debug("Adding Market Lens button at {},{}", x, y);
		return geWidgets.iconButton(parent, MarketLensSprite.CHART_ICON, NAME, "View prices", x, y,
			GeWidgets.SMALL_BUTTON_SIZE, GeWidgets.SMALL_BUTTON_SIZE,
			() -> onClick.accept(currentItem()), () -> onHover.accept(currentItem())).getWidget();
	}

	private int currentItem()
	{
		return itemManager.canonicalize(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH));
	}
}

package com.marketlens.ge;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

/** The offer being set up in the GE. Client thread only. */
@Singleton
public class GeOffer
{
	/**
	 * Price per item of the offer being set up; a 64-bit ("long") varp. Not named in RuneLite's gameval constants
	 * yet; identified by watching it follow the GE's -5%/+5% buttons (137 -> 143 -> 150 -> 143).
	 */
	private static final int PRICE_VARP = 5753;

	private final Client client;
	private final ItemManager itemManager;

	@Inject
	GeOffer(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/** The price per item chosen for {@code itemId} on the GE's offer setup screen, or null if none is being set up. */
	public Long priceFor(int itemId)
	{
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isHidden())
		{
			return null;
		}
		int searched = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (searched <= 0 || itemManager.canonicalize(searched) != itemId)
		{
			return null;
		}
		long price = client.getVarpLongValue(PRICE_VARP);
		return price > 0 ? price : null;
	}
}

