package com.marketlens.price;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.Function;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Thin async client for the OSRS Wiki real-time prices API (v2).
 * Callbacks run on the OkHttp thread pool, never on the client thread.
 */
@Slf4j
@Singleton
public class WikiPriceClient
{
	private static final HttpUrl BASE_URL = HttpUrl.get("https://prices.runescape.wiki/api/v2/osrs/");
	// The wiki blocks default Java user agents and asks for a descriptive one with a way to get in touch.
	private static final String USER_AGENT = "market-lens RuneLite plugin - https://github.com/elertan/market-lens";
	// The timeseries endpoint is sometimes slow to answer; RuneLite's default timeout gives up too early.
	private static final long READ_TIMEOUT_SECONDS = 30;

	private static final Type LATEST_TYPE = new TypeToken<Map<Integer, LatestPrice>>() {}.getType();
	private static final Type TIMESERIES_TYPE = new TypeToken<List<TimeseriesPoint>>() {}.getType();
	private static final Type MAPPING_TYPE = new TypeToken<List<ItemMapping>>() {}.getType();

	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	WikiPriceClient(OkHttpClient http, Gson gson)
	{
		this.http = http.newBuilder().readTimeout(READ_TIMEOUT_SECONDS, TimeUnit.SECONDS).build();
		this.gson = gson;
	}

	/** Live price of one item. Calls back with null if the item has no recent trades. */
	public void fetchLatest(int itemId, Consumer<LatestPrice> onSuccess, Runnable onFailure)
	{
		HttpUrl url = url("latest").newBuilder()
			.addQueryParameter("id", Integer.toString(itemId))
			.build();
		get(url, r -> WikiPriceClient.<Map<Integer, LatestPrice>>parseData(gson, r, LATEST_TYPE).get(itemId),
			onSuccess, onFailure);
	}

	public void fetchMapping(Consumer<Map<Integer, ItemMapping>> onSuccess, Runnable onFailure)
	{
		get(url("mapping"), r -> parseMapping(gson, r), onSuccess, onFailure);
	}

	public void fetchTimeseries(int itemId, Timeframe timeframe, Consumer<List<TimeseriesPoint>> onSuccess, Runnable onFailure)
	{
		HttpUrl url = url("timeseries").newBuilder()
			.addQueryParameter("id", Integer.toString(itemId))
			.addQueryParameter("lookback", timeframe.getLookback())
			.build();
		get(url, r -> parseData(gson, r, TIMESERIES_TYPE), onSuccess, onFailure);
	}

	/** Unwraps the {@code {"data": ...}} envelope used by every endpoint except /mapping. */
	static <T> T parseData(Gson gson, Reader reader, Type dataType)
	{
		JsonObject root = gson.fromJson(reader, JsonObject.class);
		return gson.fromJson(root.get("data"), dataType);
	}

	static Map<Integer, ItemMapping> parseMapping(Gson gson, Reader reader)
	{
		List<ItemMapping> list = gson.fromJson(reader, MAPPING_TYPE);
		Map<Integer, ItemMapping> byId = new HashMap<>(list.size() * 2);
		for (ItemMapping m : list)
		{
			byId.put(m.getId(), m);
		}
		return byId;
	}

	private static long elapsedMs(long startedNanos)
	{
		return TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startedNanos);
	}

	private static HttpUrl url(String endpoint)
	{
		return BASE_URL.newBuilder().addPathSegment(endpoint).build();
	}

	private <T> void get(HttpUrl url, Function<Reader, T> parser, Consumer<T> onSuccess, Runnable onFailure)
	{
		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		long started = System.nanoTime();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Request to {} failed after {} ms", url, elapsedMs(started), e);
				onFailure.run();
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.debug("Request to {} returned HTTP {} after {} ms", url, response.code(), elapsedMs(started));
						onFailure.run();
						return;
					}
					T result = parser.apply(body.charStream());
					log.debug("Request to {} took {} ms", url, elapsedMs(started));
					onSuccess.accept(result);
				}
				catch (RuntimeException e)
				{
					log.debug("Unable to parse response from {}", url, e);
					onFailure.run();
				}
			}
		});
	}
}

package com.marketlens.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.ClientUI;

/**
 * TradingView-style cross cursor over the chart. Leaving the chart restores the client's default cursor, which
 * is the one the Custom Cursor plugin set, if any: {@link ClientUI#setCursor(Cursor)} does not replace it.
 * AWT thread.
 */
@Singleton
public class ChartCursor
{
	/** Arm length from the centre pixel. */
	private static final int ARM = 7;

	private final ClientUI clientUI;
	private Cursor cross;
	private boolean shown;

	@Inject
	ChartCursor(ClientUI clientUI)
	{
		this.clientUI = clientUI;
	}

	/** Shows the cross while {@code overChart}, the default cursor otherwise. Cheap to call on every mouse move. */
	public void update(boolean overChart)
	{
		if (overChart == shown)
		{
			return;
		}
		shown = overChart;
		clientUI.setCursor(overChart ? cross() : clientUI.getDefaultCursor());
	}

	private Cursor cross()
	{
		if (cross == null)
		{
			cross = createCross();
		}
		return cross;
	}

	/** A 1-px white cross with a dark outline, so it stays visible on the light chart text and grid too. */
	private static Cursor createCross()
	{
		Toolkit toolkit = Toolkit.getDefaultToolkit();
		Dimension size = toolkit.getBestCursorSize(2 * ARM + 3, 2 * ARM + 3);
		BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		int c = Math.min(size.width, size.height) / 2;
		Graphics2D g = image.createGraphics();
		g.setColor(Color.BLACK);
		g.fillRect(c - ARM - 1, c - 1, 2 * ARM + 3, 3);
		g.fillRect(c - 1, c - ARM - 1, 3, 2 * ARM + 3);
		g.setColor(Color.WHITE);
		g.fillRect(c - ARM, c, 2 * ARM + 1, 1);
		g.fillRect(c, c - ARM, 1, 2 * ARM + 1);
		g.dispose();
		return toolkit.createCustomCursor(image, new Point(c, c), "Market Lens chart");
	}
}

package com.marketlens.ui;

import com.marketlens.MarketLensConfig;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;

/**
 * Chart mouse handling on the AWT thread: hover for the crosshair, wheel to zoom (anchored on the right
 * edge, or on the cursor with Shift/Ctrl), left-drag to pan, double-click to reset, and the cross cursor
 * over the plot. Events inside the plot are consumed so the game camera does not zoom or walk.
 */
@Singleton
public class ChartInput implements MouseListener, MouseWheelListener
{
	private static final double ZOOM_STEP = 1.15;

	private final ChartState state;
	private final ChartCursor cursor;
	private final MarketLensConfig config;
	private int dragLastX = -1;

	@Inject
	ChartInput(ChartState state, ChartCursor cursor, MarketLensConfig config)
	{
		this.state = state;
		this.cursor = cursor;
		this.config = config;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		Rectangle plot = state.getPlotBounds();
		if (plot == null || !plot.contains(e.getPoint()))
		{
			return e;
		}
		// Like TradingView: the wheel zooms around the newest visible data (only the left edge moves);
		// with Shift or Ctrl held it zooms around the cursor. Wheel down (positive rotation) zooms out.
		double anchor = e.isShiftDown() || e.isControlDown() ? timeAt(plot, e.getX()) : state.getViewport().getEnd();
		state.getViewport().zoom(Math.pow(ZOOM_STEP, e.getPreciseWheelRotation()), anchor);
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		Rectangle plot = state.getPlotBounds();
		if (e.getButton() == MouseEvent.BUTTON1 && plot != null && plot.contains(e.getPoint()))
		{
			dragLastX = e.getX();
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		Rectangle plot = state.getPlotBounds();
		if (dragLastX < 0 || plot == null)
		{
			return e;
		}
		double span = state.getViewport().getEnd() - state.getViewport().getStart();
		state.getViewport().pan(-(e.getX() - dragLastX) * span / plot.width);
		dragLastX = e.getX();
		state.setHover(e.getX(), e.getY());
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (dragLastX >= 0)
		{
			dragLastX = -1;
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		Rectangle plot = state.getPlotBounds();
		if (plot != null && plot.contains(e.getPoint()))
		{
			if (e.getClickCount() >= 2)
			{
				state.getViewport().reset();
			}
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		Rectangle plot = state.getPlotBounds();
		boolean overPlot = plot != null && plot.contains(e.getPoint());
		if (overPlot)
		{
			state.setHover(e.getX(), e.getY());
		}
		else
		{
			state.clearHover();
		}
		cursor.update(overPlot && config.crossCursor());
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		state.clearHover();
		cursor.update(false);
		return e;
	}

	private double timeAt(Rectangle plot, int x)
	{
		double start = state.getViewport().getStart();
		double end = state.getViewport().getEnd();
		return start + (double) (x - plot.x) / plot.width * (end - start);
	}
}

package com.marketlens.ui;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the chart into the chart area of one of the windows, if that window is showing. */
abstract class ChartOverlay extends Overlay
{
	private final ChartRenderer renderer;

	ChartOverlay(ChartRenderer renderer)
	{
		this.renderer = renderer;
		setPosition(OverlayPosition.DYNAMIC);
	}

	/** Canvas bounds of the window's chart area, or null when that window isn't showing. */
	abstract Rectangle chartBounds();

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Rectangle area = chartBounds();
		// Widgets the client hasn't drawn yet report position -1,-1; drawing then would flash the chart in the
		// top-left corner for a frame. A real chart area lies inside its window, so never at negative coordinates.
		if (area != null && area.x >= 0 && area.y >= 0)
		{
			renderer.render(graphics, area);
		}
		return null;
	}
}

package com.marketlens.ui;

import com.marketlens.MarketLensConfig;
import com.marketlens.chart.AxisTicks;
import com.marketlens.chart.Candle;
import com.marketlens.chart.Candles;
import com.marketlens.chart.ChartType;
import com.marketlens.chart.ChartScale;
import com.marketlens.chart.Downsample;
import com.marketlens.chart.LabelLayout;
import com.marketlens.chart.PriceFormat;
import com.marketlens.ge.GeOffer;
import com.marketlens.price.LatestPrice;
import com.marketlens.price.PriceService;
import com.marketlens.price.TimeseriesPoint;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;

/**
 * Draws the price chart into a given area: grid, axes, volume bars, high/low lines or candlesticks, live price
 * tags, the price chosen on the GE offer screen and a TradingView-style crosshair. Shared by the normal and the expanded chart, so both look the same at any size.
 * The geometry lives in {@link ChartScale}; this class only draws. When buckets would be drawn closer than a few
 * pixels apart, they are merged first ({@link Downsample}), so dense series stay readable. Client thread only.
 */
@Singleton
public class ChartRenderer
{
	private static final int INSET = 4;
	private static final int PRICE_AXIS_WIDTH = 50;
	private static final int TIME_AXIS_HEIGHT = 16;
	private static final int LEGEND_HEIGHT = 16;
	private static final int MIN_PX_PER_PRICE_TICK = 24;
	private static final int MIN_PX_PER_TIME_TICK = 64;
	private static final int MIN_PX_PER_DOT = 5;
	/** Below this spacing, neighbouring buckets are merged so the lines stay readable (see {@link Downsample}). */
	private static final int MIN_PX_PER_POINT = 2;
	/** Candles need room for a visible body, so they are merged until they are at least this far apart. */
	private static final int MIN_PX_PER_CANDLE = 5;
	/** Candle body width as a fraction of the space per candle. */
	private static final double CANDLE_BODY_FRACTION = 0.6;
	/** Volume bars and the dashed live-price lines use the buy/sell colour, partly transparent. */
	private static final int VOLUME_ALPHA = 110;
	private static final int TAG_LINE_ALPHA = 140;
	private static final int DOT_SIZE = 3;

	private static final Stroke LINE = new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final Stroke THIN = new BasicStroke(1f);
	private static final Stroke DASHED = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER,
		10f, new float[]{3f, 3f}, 0f);

	private final ChartState state;
	private final PriceService prices;
	private final GeOffer offer;
	private final MarketLensConfig config;
	private final ZoneId zone = ZoneId.systemDefault();
	/** Pixel bounds of the digits in the chart font; measured once, used to centre labels. */
	private Rectangle2D digitBounds;
	/** Last merge result, reused until the series or the interval changes. */
	private List<TimeseriesPoint> mergedSource;
	private long mergedInterval;
	private List<TimeseriesPoint> merged;
	/** Last candle build, reused until the series or the interval changes; candlePoints match candles by index. */
	private List<TimeseriesPoint> candleSource;
	private long candleInterval;
	private List<Candle> candles;
	private List<TimeseriesPoint> candlePoints;

	@Inject
	ChartRenderer(ChartState state, PriceService prices, GeOffer offer, MarketLensConfig config)
	{
		this.state = state;
		this.prices = prices;
		this.offer = offer;
		this.config = config;
	}

	/** Draws the chart for the current item and timeframe into {@code area} (canvas coordinates). */
	public void render(Graphics2D graphics, Rectangle area)
	{
		PriceService.Series series = prices.getSeries(state.getItemId(), state.getTimeframe());
		state.sync(series.getPoints());

		Rectangle plot = new Rectangle(area.x + INSET, area.y + LEGEND_HEIGHT,
			area.width - PRICE_AXIS_WIDTH - INSET, area.height - LEGEND_HEIGHT - TIME_AXIS_HEIGHT);
		state.setPlotBounds(plot);

		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			Font font = FontManager.getRunescapeSmallFont();
			g.setFont(font);
			if (digitBounds == null)
			{
				digitBounds = font.createGlyphVector(g.getFontRenderContext(), "0123456789").getVisualBounds();
			}
			ChartText text = new ChartText(g, digitBounds);

			if (series.getPoints().isEmpty())
			{
				text.drawCentered(statusText(series.getStatus()), area.x + area.width / 2, area.y + area.height / 2,
					Palette.TEXT_ORANGE);
				return;
			}

			double start = state.getViewport().getStart();
			double end = state.getViewport().getEnd();
			boolean candleMode = state.getChartType() == ChartType.CANDLES;
			long interval = Downsample.interval(state.getBucketSeconds(), (end - start) / plot.width,
				candleMode ? MIN_PX_PER_CANDLE : MIN_PX_PER_POINT);
			List<Candle> candleList = candleMode ? candlesAt(series.getPoints(), interval) : null;
			List<TimeseriesPoint> points = candleMode ? candlePoints : pointsAt(series.getPoints(), interval);
			if (points.isEmpty())
			{
				text.drawCentered(statusText(PriceService.Status.READY), area.x + area.width / 2,
					area.y + area.height / 2, Palette.TEXT_ORANGE);
				return;
			}

			LatestPrice latest = prices.getLatest(state.getItemId());
			Long offerPrice = config.showOfferLine() ? offer.priceFor(state.getItemId()) : null;
			ChartScale scale = new ChartScale(points, start, end, interval, plot, config.showVolume(),
				latest == null || latest.getHigh() == null ? null : latest.getHigh().doubleValue(),
				latest == null || latest.getLow() == null ? null : latest.getLow().doubleValue(),
				offerPrice == null ? null : offerPrice.doubleValue());
			new Frame(g, text, area, scale, points, candleList, interval, latest, offerPrice).draw();
		}
		finally
		{
			g.dispose();
		}
	}

	/** The series at {@code interval}: the raw points, or merged ones when the raw buckets are too dense. */
	private List<TimeseriesPoint> pointsAt(List<TimeseriesPoint> points, long interval)
	{
		if (interval == state.getBucketSeconds())
		{
			return points;
		}
		if (points != mergedSource || interval != mergedInterval)
		{
			merged = Downsample.merge(points, interval);
			mergedSource = points;
			mergedInterval = interval;
		}
		return merged;
	}

	/** Candles for the series at {@code interval}; also fills {@link #candlePoints}. */
	private List<Candle> candlesAt(List<TimeseriesPoint> points, long interval)
	{
		if (points != candleSource || interval != candleInterval)
		{
			candles = Candles.build(points, interval);
			candlePoints = candles.stream().map(Candle::asPoint).collect(Collectors.toList());
			candleSource = points;
			candleInterval = interval;
		}
		return candles;
	}

	private static String statusText(PriceService.Status status)
	{
		switch (status)
		{
			case LOADING:
				return "Loading prices...";
			case FAILED:
				return "Price data unavailable, retrying...";
			default:
				return "No trades in this period";
		}
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
	}

	/** One frame of chart drawing, in back-to-front order. */
	private final class Frame
	{
		private final Graphics2D g;
		private final ChartText text;
		private final Rectangle area;
		private final ChartScale scale;
		private final Rectangle plot;
		private final List<TimeseriesPoint> points;
		/** The candles behind {@link #points} in candle mode, by the same index; null for the line chart. */
		private final List<Candle> candles;
		/** Seconds per point: the series' bucket size, or the merged interval. */
		private final long interval;
		private final LatestPrice latest;
		/** Price chosen on the GE offer screen, or null. */
		private final Long offerPrice;
		/** Colours and options from the config, read once per frame. */
		private final Color buy;
		private final Color sell;
		private final boolean twelveHour;

		Frame(Graphics2D g, ChartText text, Rectangle area, ChartScale scale, List<TimeseriesPoint> points,
			List<Candle> candles, long interval, LatestPrice latest, Long offerPrice)
		{
			this.g = g;
			this.text = text;
			this.area = area;
			this.scale = scale;
			this.plot = scale.getPlot();
			this.points = points;
			this.candles = candles;
			this.interval = interval;
			this.latest = latest;
			this.offerPrice = offerPrice;
			this.buy = config.buyColor();
			this.sell = config.sellColor();
			this.twelveHour = config.timeFormat().isTwelveHour();
		}

		void draw()
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			List<Tag> tags = layoutTags();
			drawPriceGrid(tags);
			drawTimeGrid();

			Shape clip = g.getClip();
			g.clip(plot);
			if (scale.getVolumePane().height > 0)
			{
				drawVolume();
			}
			if (candles != null)
			{
				drawCandles();
			}
			else
			{
				drawLine(TimeseriesPoint::getAvgHighPrice, buy);
				drawLine(TimeseriesPoint::getAvgLowPrice, sell);
			}
			g.setClip(clip);

			drawTags(tags);
			int hovered = drawCrosshair();
			drawLegend(hovered >= 0 ? hovered : scale.getLast());
		}

		/** Candlesticks: a 1-px wick from high to low and a body from open to close, green when it closed higher. */
		private void drawCandles()
		{
			int body = Math.max(1, (int) (scale.bucketWidth() * CANDLE_BODY_FRACTION));
			if (body % 2 == 0)
			{
				body--;  // odd width keeps the wick in the middle
			}
			// Crisp pixels: no anti-aliasing for the boxes and wicks.
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			g.setStroke(THIN);
			for (int i = scale.getFirst(); i <= scale.getLast(); i++)
			{
				Candle c = candles.get(i);
				int x = scale.x(c.getTimestamp());
				int top = scale.y(Math.max(c.getOpen(), c.getClose()));
				int bottom = scale.y(Math.min(c.getOpen(), c.getClose()));
				g.setColor(c.isUp() ? buy : sell);
				g.drawLine(x, scale.y(c.getHigh()), x, scale.y(c.getLow()));
				g.fillRect(x - body / 2, top, body, Math.max(1, bottom - top + 1));
			}
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		}

		/** Horizontal grid + right axis labels, leaving out labels that a price tag would cover. */
		private void drawPriceGrid(List<Tag> tags)
		{
			Rectangle pane = scale.getPricePane();
			List<Double> ticks = AxisTicks.prices(scale.getMin(), scale.getMax(), Math.max(2, pane.height / MIN_PX_PER_PRICE_TICK));
			double step = ticks.size() > 1 ? ticks.get(1) - ticks.get(0) : 1;
			int labelX = plot.x + plot.width + 4;
			for (double tick : ticks)
			{
				int y = scale.y(tick);
				g.setColor(Palette.GRID);
				g.drawLine(plot.x, y, plot.x + plot.width, y);
				if (tags.stream().noneMatch(tag -> Math.abs(tag.labelY - y) < text.labelHeight()))
				{
					text.draw(PriceFormat.axis(tick, step), labelX, text.baselineFor(y), Palette.AXIS_TEXT);
				}
			}
		}

		/** Vertical grid + bottom axis labels. */
		private void drawTimeGrid()
		{
			double start = scale.getStart();
			double end = scale.getEnd();
			long step = AxisTicks.timeStep(start, end, Math.max(2, plot.width / MIN_PX_PER_TIME_TICK));
			int labelY = plot.y + plot.height + text.ascent() + 3;
			for (long tick : AxisTicks.times(start, end, step, zone))
			{
				int x = scale.x(tick);
				g.setColor(Palette.GRID);
				g.drawLine(x, plot.y, x, plot.y + plot.height);

				String label = AxisTicks.timeLabel(tick, step, zone, twelveHour);
				int labelX = x - text.width(label) / 2;
				if (labelX >= area.x && labelX + text.width(label) <= plot.x + plot.width)
				{
					text.draw(label, labelX, labelY, Palette.AXIS_TEXT);
				}
			}
		}

		/** Stacked bars: instant-buy volume at the bottom, instant-sell volume on top. */
		private void drawVolume()
		{
			Rectangle pane = scale.getVolumePane();
			int barWidth = Math.max(1, (int) scale.bucketWidth() - 1);
			int bottom = pane.y + pane.height;
			Color buyVolume = withAlpha(buy, VOLUME_ALPHA);
			Color sellVolume = withAlpha(sell, VOLUME_ALPHA);
			for (int i = scale.getFirst(); i <= scale.getLast(); i++)
			{
				TimeseriesPoint p = points.get(i);
				int x = scale.x(p.getTimestamp()) - barWidth / 2;
				int buyHeight = scale.volumeHeight(p.getHighPriceVolume());
				int sellHeight = scale.volumeHeight(p.getLowPriceVolume());
				g.setColor(buyVolume);
				g.fillRect(x, bottom - buyHeight, barWidth, buyHeight);
				g.setColor(sellVolume);
				g.fillRect(x, bottom - buyHeight - sellHeight, barWidth, sellHeight);
			}
		}

		/**
		 * Polyline through the bucket averages. Buckets without trades are skipped, so the line connects
		 * the surrounding prices; it also reaches back/forward past the view edges so it never starts mid-plot.
		 * Points get a dot once they are far enough apart to tell apart.
		 */
		private void drawLine(Function<TimeseriesPoint, Double> price, Color color)
		{
			int from = scale.getFirst();
			while (from > 0 && price.apply(points.get(from)) == null)
			{
				from--;
			}
			int to = scale.getLast();
			while (to < points.size() - 1 && price.apply(points.get(to)) == null)
			{
				to++;
			}

			boolean dots = scale.bucketWidth() >= MIN_PX_PER_DOT;
			Path2D path = new Path2D.Double();
			boolean started = false;
			g.setColor(color);
			for (int i = from; i <= to; i++)
			{
				TimeseriesPoint p = points.get(i);
				Double value = price.apply(p);
				if (value == null)
				{
					continue;
				}
				int px = scale.x(p.getTimestamp());
				int py = scale.y(value);
				if (started)
				{
					path.lineTo(px, py);
				}
				else
				{
					path.moveTo(px, py);
					started = true;
				}
				if (dots)
				{
					g.fillOval(px - DOT_SIZE / 2, py - DOT_SIZE / 2, DOT_SIZE, DOT_SIZE);
				}
			}
			g.setStroke(LINE);
			g.draw(path);
		}

		/** Live prices and the chosen offer price as tags on the price axis, moved apart where they would overlap. */
		private List<Tag> layoutTags()
		{
			List<Tag> tags = new ArrayList<>();
			if (latest != null)
			{
				addTag(tags, latest.getHigh(), buy, withAlpha(buy, TAG_LINE_ALPHA));
				addTag(tags, latest.getLow(), sell, withAlpha(sell, TAG_LINE_ALPHA));
			}
			addTag(tags, offerPrice, Palette.OFFER_COLOR, Palette.OFFER_TAG_LINE);

			Rectangle pane = scale.getPricePane();
			int[] lineYs = tags.stream().mapToInt(tag -> tag.lineY).toArray();
			int[] labelYs = LabelLayout.separate(lineYs, text.labelHeight(), pane.y, pane.y + pane.height);
			for (int i = 0; i < tags.size(); i++)
			{
				tags.get(i).labelY = labelYs[i];
			}
			return tags;
		}

		private void addTag(List<Tag> tags, Long price, Color color, Color lineColor)
		{
			if (price != null && price >= scale.getMin() && price <= scale.getMax())
			{
				tags.add(new Tag(price, color, lineColor, scale.y(price)));
			}
		}

		/** Dashed line at the exact price, coloured label at its (possibly moved) position on the axis. */
		private void drawTags(List<Tag> tags)
		{
			g.setStroke(DASHED);
			for (Tag tag : tags)
			{
				g.setColor(tag.lineColor);
				g.drawLine(plot.x, tag.lineY, plot.x + plot.width, tag.lineY);
			}
			for (Tag tag : tags)
			{
				text.drawBox(PriceFormat.axis(tag.price, 1), plot.x + plot.width + 1, tag.labelY, PRICE_AXIS_WIDTH - 2,
					tag.color, Color.BLACK);
			}
		}

		/** Crosshair snapped to the nearest point. Returns that point's index, or -1 when not hovering. */
		private int drawCrosshair()
		{
			int mx = state.getHoverX();
			int my = state.getHoverY();
			if (!plot.contains(mx, my))
			{
				return -1;
			}

			int index = scale.nearestIndex(scale.timeAt(mx));
			TimeseriesPoint nearest = points.get(index);
			int x = scale.x(nearest.getTimestamp());
			g.setStroke(DASHED);
			g.setColor(Palette.CROSSHAIR);
			g.drawLine(x, plot.y, x, plot.y + plot.height);
			if (scale.getPricePane().contains(mx, my))
			{
				// GE prices are whole coins, so by default the line snaps to the nearest one instead of a fraction.
				double price = scale.priceAt(my);
				int y = my;
				if (config.snapCrosshairToCoins())
				{
					price = Math.round(price);
					y = scale.y(price);
				}
				g.drawLine(plot.x, y, plot.x + plot.width, y);
				text.drawBox(PriceFormat.axis(price, 1), plot.x + plot.width + 1, y, PRICE_AXIS_WIDTH - 2,
					Palette.LABEL_BACKGROUND, Palette.TEXT);
			}

			String time = AxisTicks.crosshairLabel(nearest.getTimestamp(), interval, zone, twelveHour);
			int w = text.width(time) + 8;
			int boxX = Math.max(area.x, Math.min(x - w / 2, plot.x + plot.width - w));
			int boxY = plot.y + plot.height + 1;
			int boxHeight = TIME_AXIS_HEIGHT - 2;
			g.setColor(Palette.LABEL_BACKGROUND);
			g.fillRect(boxX, boxY, w, boxHeight);
			text.draw(time, boxX + 4, text.baselineFor(boxY + boxHeight / 2), Palette.TEXT);
			return index;
		}

		/**
		 * Readout for the hovered or newest point: "High 828,861  Low 808,000  Vol 16" for lines,
		 * "O 137  H 139  L 134  C 136  Vol 16" for candles (close coloured by direction).
		 */
		private void drawLegend(int index)
		{
			TimeseriesPoint p = points.get(index);
			int x = area.x + INSET;
			int y = area.y + text.ascent() + 3;
			if (candles != null)
			{
				Candle c = candles.get(index);
				x = legendItem("O ", c.getOpen(), Palette.TEXT, x, y);
				x = legendItem("H ", c.getHigh(), Palette.TEXT, x, y);
				x = legendItem("L ", c.getLow(), Palette.TEXT, x, y);
				x = legendItem("C ", c.getClose(), c.isUp() ? buy : sell, x, y);
			}
			else
			{
				x = legendItem("High ", p.getAvgHighPrice(), buy, x, y);
				x = legendItem("Low ", p.getAvgLowPrice(), sell, x, y);
			}
			text.draw("Vol ", x, y, Palette.TEXT_MUTED);
			text.draw(PriceFormat.exact(p.totalVolume()), x + text.width("Vol "), y, Palette.TEXT);
		}

		private int legendItem(String label, Double value, Color color, int x, int y)
		{
			text.draw(label, x, y, Palette.TEXT_MUTED);
			x += text.width(label);
			String formatted = value == null ? "-" : PriceFormat.exact(Math.round(value));
			text.draw(formatted, x, y, color);
			return x + text.width(formatted) + 10;
		}
	}

	/** A live-price tag: its dashed line sits at the exact price, its label may be moved to avoid overlap. */
	private static final class Tag
	{
		private final long price;
		private final Color color;
		private final Color lineColor;
		private final int lineY;
		private int labelY;

		Tag(long price, Color color, Color lineColor, int lineY)
		{
			this.price = price;
			this.color = color;
			this.lineColor = lineColor;
			this.lineY = lineY;
		}
	}
}

package com.marketlens.ui;

import com.marketlens.chart.ChartType;
import com.marketlens.chart.ChartViewport;
import com.marketlens.price.Timeframe;
import com.marketlens.price.TimeseriesPoint;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;

/**
 * What the price window is showing: item, timeframe, zoom and hover.
 * Shared by the widget window, the chart overlay (client thread) and mouse input (AWT thread).
 */
@Singleton
public class ChartState
{
	private static final int MIN_VISIBLE_BUCKETS = 6;
	/** Empty buckets after the newest point, so its dot isn't drawn against the price axis (like TradingView's right offset). */
	private static final int RIGHT_OFFSET_BUCKETS = 2;

	@Getter
	private final ChartViewport viewport = new ChartViewport();
	@Getter
	private volatile int itemId = -1;
	@Getter
	private volatile Timeframe timeframe = Timeframe.ONE_DAY;
	@Getter
	@Setter
	private volatile ChartType chartType = ChartType.LINE;
	/** Plot area in canvas coordinates, published by the renderer every frame for mouse input. */
	@Getter
	@Setter
	private volatile Rectangle plotBounds;
	@Getter
	private volatile int hoverX = -1;
	@Getter
	private volatile int hoverY = -1;
	/** Bucket width of the applied series, in seconds. */
	@Getter
	private volatile long bucketSeconds = 300;

	private List<TimeseriesPoint> appliedPoints;

	public boolean isOpen()
	{
		return itemId > 0;
	}

	public void open(int itemId, Timeframe timeframe)
	{
		this.itemId = itemId;
		this.timeframe = timeframe;
		appliedPoints = null;
	}

	public void close()
	{
		itemId = -1;
		appliedPoints = null;
		plotBounds = null;
		clearHover();
	}

	public void setTimeframe(Timeframe timeframe)
	{
		this.timeframe = timeframe;
		appliedPoints = null;
	}

	public void setHover(int x, int y)
	{
		hoverX = x;
		hoverY = y;
	}

	public void clearHover()
	{
		setHover(-1, -1);
	}

	/** Points the viewport at new series data: a fresh view for a new series, a range update for a refresh. Client thread. */
	public void sync(List<TimeseriesPoint> points)
	{
		if (points == appliedPoints || points.isEmpty())
		{
			return;
		}

		long step = bucketSeconds(points);
		bucketSeconds = step;
		long first = points.get(0).getTimestamp();
		long last = points.get(points.size() - 1).getTimestamp() + step * RIGHT_OFFSET_BUCKETS;
		if (appliedPoints == null)
		{
			viewport.setData(first, last, step * MIN_VISIBLE_BUCKETS, timeframe.getInitialWindowSeconds());
		}
		else
		{
			viewport.updateRange(first, last);
		}
		appliedPoints = points;
	}

	/** Bucket width of a series, taken as the smallest gap between consecutive points. */
	private static long bucketSeconds(List<TimeseriesPoint> points)
	{
		long step = Long.MAX_VALUE;
		for (int i = 1; i < points.size(); i++)
		{
			long gap = points.get(i).getTimestamp() - points.get(i - 1).getTimestamp();
			if (gap > 0 && gap < step)
			{
				step = gap;
			}
		}
		return step == Long.MAX_VALUE ? 300 : step;
	}
}

package com.marketlens.ui;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;

/** Text drawing for the chart, in the OSRS style, with labels centred on the real pixel height of digits. */
final class ChartText
{
	/** Vertical padding inside axis label boxes, top and bottom combined. */
	private static final int LABEL_PADDING = 6;

	private final Graphics2D g;
	private final Rectangle2D digitBounds;

	/** @param digitBounds visual bounds of "0123456789" in the current font, relative to the baseline */
	ChartText(Graphics2D g, Rectangle2D digitBounds)
	{
		this.g = g;
		this.digitBounds = digitBounds;
	}

	/** OSRS-style text: one-pixel black drop shadow. */
	void draw(String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	void drawCentered(String text, int centerX, int y, Color color)
	{
		draw(text, centerX - width(text) / 2, y, color);
	}

	/** A filled label box of {@code width} on an axis, with text vertically centred on {@code centerY}. */
	void drawBox(String text, int x, int centerY, int width, Color background, Color foreground)
	{
		int h = labelHeight();
		g.setColor(background);
		g.fillRect(x, centerY - h / 2, width, h);
		g.setColor(foreground);
		g.drawString(text, x + 3, baselineFor(centerY));
	}

	int width(String text)
	{
		return metrics().stringWidth(text);
	}

	int ascent()
	{
		return metrics().getAscent();
	}

	int labelHeight()
	{
		return (int) Math.ceil(digitBounds.getHeight()) + LABEL_PADDING;
	}

	/** Baseline that puts digits visually centred on {@code centerY}. */
	int baselineFor(int centerY)
	{
		return centerY - (int) Math.round(digitBounds.getY() + digitBounds.getHeight() / 2);
	}

	private FontMetrics metrics()
	{
		return g.getFontMetrics();
	}
}

package com.marketlens.ui;

import com.marketlens.chart.ChartType;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Consumer;
import net.runelite.api.widgets.Widget;

/**
 * Two icon buttons, line and candles, the size of the expand button, that switch the chart type;
 * the active one is highlighted.
 */
class ChartTypeToggle
{
	static final int BUTTON_WIDTH = 26;
	static final int BUTTON_HEIGHT = 30;
	private static final int GAP = 2;
	static final int WIDTH = 2 * BUTTON_WIDTH + GAP;

	private final Map<ChartType, IconButton> buttons = new EnumMap<>(ChartType.class);

	/** Builds the pair with its top-left at x,y in {@code parent}. */
	ChartTypeToggle(GeWidgets geWidgets, Widget parent, int x, int y, ChartType selected, Consumer<ChartType> onSelect)
	{
		add(geWidgets, parent, ChartType.LINE, MarketLensSprite.LINE_ICON, x, y, onSelect);
		add(geWidgets, parent, ChartType.CANDLES, MarketLensSprite.CANDLE_ICON, x + BUTTON_WIDTH + GAP, y, onSelect);
		select(selected);
	}

	void select(ChartType type)
	{
		buttons.forEach((t, button) -> button.setSelected(t == type));
	}

	/** The chart type of the button at canvas point x,y, or null. */
	ChartType at(int x, int y)
	{
		for (Map.Entry<ChartType, IconButton> button : buttons.entrySet())
		{
			if (button.getValue().getWidget().getBounds().contains(x, y))
			{
				return button.getKey();
			}
		}
		return null;
	}

	private void add(GeWidgets geWidgets, Widget parent, ChartType type, MarketLensSprite icon, int x, int y,
		Consumer<ChartType> onSelect)
	{
		buttons.put(type, geWidgets.iconButton(parent, icon, type.getMenuName(), "Show", x, y,
			BUTTON_WIDTH, BUTTON_HEIGHT, () -> onSelect.accept(type), () -> {}));
	}
}

