 * GE frame, title bar, back arrow, price summary, timeframe tabs, a line/candles toggle and an expand button.
 * The chart itself is drawn by {@link GeChartOverlay} inside {@link #getChartBounds()}; the expand button
 * opens it in the {@link ExpandedChartWindow}. Client thread only, except {@link #keyPressed}.
 */
@Singleton
public class PriceWindow extends GeWindow implements KeyListener
{
	/** Content starts below the frame's title divider. */
	private static final int CONTENT_TOP = 40;
	/** Row above the chart with the timeframe tabs and the expand button, which is taller than the tabs. */
	private static final int TAB_ROW_HEIGHT = 30;
	private static final int TABS_TO_CHART = 4;
	private static final int CHART_TOP = CONTENT_TOP + TAB_ROW_HEIGHT;
	private static final int PAD = 10;
	private static final int SUMMARY_WIDTH = 150;
	private static final int ROW_HEIGHT = 15;
	private static final int TOGGLE_TO_EXPAND = 4;
	private static final int EXPAND_BUTTON_WIDTH = 26;
	private static final int EXPAND_BUTTON_HEIGHT = 30;

	private final Client client;
	private final ClientThread clientThread;
	private final PriceService prices;
	private final ChartState state;
	private final SmallItemSprite smallItemSprite;
	private final ExpandedChartWindow expandedWindow;
	private final ConfigManager configManager;
	private final MarketLensConfig config;

	private Widget chartArea;
	private TitleBar titleBar;
	private TimeframeTabs tabs;
	private ChartTypeToggle chartTypeToggle;
	private Widget buyValue;
	private Widget buyAge;
	private Widget sellValue;
	private Widget sellAge;
	private Widget marginValue;
	private Widget taxValue;
	private Widget profitValue;
	private Widget limitValue;
	private Widget volumeValue;

	@Inject
	PriceWindow(Client client, ClientThread clientThread, PriceService prices, ChartState state, WidgetFactory widgets,
		GeWidgets geWidgets, SmallItemSprite smallItemSprite, ExpandedChartWindow expandedWindow,
		ConfigManager configManager, MarketLensConfig config)
	{
		super(widgets, geWidgets);
		this.client = client;
		this.clientThread = clientThread;
		this.prices = prices;
		this.state = state;
		this.smallItemSprite = smallItemSprite;
		this.expandedWindow = expandedWindow;
		this.configManager = configManager;
		this.config = config;
	}

	public void open(int itemId, Timeframe timeframe, ChartType chartType)
	{
		state.open(itemId, timeframe);
		state.setChartType(chartType);
		prices.refresh(itemId, timeframe);
		if (attach())
		{
			refresh();
		}
		else
		{
			state.close();
		}
	}

	public void close()
	{
		expandedWindow.close();
		state.close();
		detach();
		smallItemSprite.clear();
	}

	/** Every client tick: rebuilds the windows if the game discarded their widgets while they should be open. */
	public void ensureAttached()
	{
		boolean rebuilt = state.isOpen() && reattachIfLost();
		if (expandedWindow.ensureAttached() || rebuilt)
		{
			refresh();
		}
	}

	/** Every game tick while open: keeps the prices current and the "Traded ... ago" texts ticking. */
	public void onGameTick()
	{
		if (state.isOpen())
		{
			prices.refresh(state.getItemId(), state.getTimeframe());
			refreshTradeAges();
		}
	}

	/** Canvas bounds of the chart area, or null when the window is not visible or the chart is expanded. */
	public Rectangle getChartBounds()
	{
		if (!state.isOpen() || !isAttached() || expandedWindow.isOpen())
		{
			return null;
		}
		return chartArea.getBounds();
	}

	/** Updates everything shown from the cached price data. Called when the window opens and when data arrives. */
	public void refresh()
	{
		if (!state.isOpen() || !isAttached())
		{
			return;
		}

		int itemId = state.getItemId();
		ItemMapping mapping = prices.getMapping(itemId);
		String itemName = mapping != null ? mapping.getName() : client.getItemDefinition(itemId).getName();
		int itemSprite = smallItemSprite.spriteFor(itemId);
		titleBar.show(itemName, itemSprite);
		tabs.select(state.getTimeframe());
		chartTypeToggle.select(state.getChartType());
		expandedWindow.refresh(itemName, itemSprite);

		int buyColor = config.buyColor().getRGB() & 0xFFFFFF;
		int sellColor = config.sellColor().getRGB() & 0xFFFFFF;
		buyValue.setTextColor(buyColor);
		sellValue.setTextColor(sellColor);

		LatestPrice latest = prices.getLatest(itemId);
		Long high = latest == null ? null : latest.getHigh();
		Long low = latest == null ? null : latest.getLow();
		buyValue.setText(high == null ? "-" : PriceFormat.exact(high));
		sellValue.setText(low == null ? "-" : PriceFormat.exact(low));
		refreshTradeAges();

		if (high != null && low != null)
		{
			long margin = high - low;
			long tax = GeTax.of(itemId, high);
			long profit = margin - tax;
			marginValue.setText(PriceFormat.signed(margin));
			taxValue.setText(tax == 0 ? "0" : "-" + PriceFormat.exact(tax));
			profitValue.setText(PriceFormat.signed(profit));
			profitValue.setTextColor(profit > 0 ? buyColor : profit < 0 ? sellColor : Palette.WHITE);
		}
		else
		{
			marginValue.setText("-");
			taxValue.setText("-");
			profitValue.setText("-");
			profitValue.setTextColor(Palette.WHITE);
		}

		Integer limit = mapping == null ? null : mapping.getLimit();
		limitValue.setText(limit == null ? "-" : PriceFormat.exact(limit));
		Long hourVolume = prices.getHourVolume(itemId);
		volumeValue.setText(hourVolume == null ? "-" : PriceFormat.exact(hourVolume));
	}

	/** Only the "Traded ... ago" texts, which change with time rather than with data. */
	private void refreshTradeAges()
	{
		if (!state.isOpen() || !isAttached())
		{
			return;
		}
		LatestPrice latest = prices.getLatest(state.getItemId());
		long now = System.currentTimeMillis() / 1000;
		buyAge.setText(latest == null || latest.getHigh() == null ? "" : "Traded " + PriceFormat.age(now - latest.getHighTime()));
		sellAge.setText(latest == null || latest.getLow() == null ? "" : "Traded " + PriceFormat.age(now - latest.getLowTime()));
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE && state.isOpen())
		{
			// Esc first leaves the expanded chart, then closes Market Lens.
			e.consume();
			clientThread.invoke(() ->
			{
				if (expandedWindow.isOpen())
				{
					expandedWindow.close();
				}
				else
				{
					close();
				}
			});
		}
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}

	@Override
	protected Widget findHost()
	{
		return client.getWidget(InterfaceID.GeOffers.UNIVERSE);
	}

	/** Exactly over the GE's own frame, so the window replaces the GE view rather than floating on the screen. */
	@Override
	protected Rectangle placement(Widget universe)
	{
		Widget frame = client.getWidget(InterfaceID.GeOffers.FRAME);
		Rectangle target = frame != null ? frame.getBounds() : universe.getBounds();
		Point origin = universe.getCanvasLocation();
		int w = Math.min(GeWidgets.FRAME_WIDTH, target.width);
		int h = Math.min(GeWidgets.FRAME_HEIGHT, target.height);
		return new Rectangle(target.x - origin.getX() + (target.width - w) / 2,
			target.y - origin.getY() + (target.height - h) / 2, w, h);
	}

	@Override
	protected void buildContent(Widget root, int w, int h)
	{
		titleBar = new TitleBar(widgets, root, geWidgets.frame(root, w, h));
		geWidgets.backArrow(root, h, this::close);
		buildSummary(root);

		int chartX = PAD + SUMMARY_WIDTH + PAD;
		int rowY = CHART_TOP - TAB_ROW_HEIGHT - TABS_TO_CHART;
		int tabsY = rowY + (TAB_ROW_HEIGHT - TimeframeTabs.height(widgets)) / 2;
		tabs = new TimeframeTabs(widgets, root, chartX, tabsY, state.getTimeframe(), this::selectTimeframe);
		int expandX = w - PAD - EXPAND_BUTTON_WIDTH;
		chartTypeToggle = new ChartTypeToggle(geWidgets, root, expandX - TOGGLE_TO_EXPAND - ChartTypeToggle.WIDTH,
			rowY, state.getChartType(), this::selectChartType);
		geWidgets.iconButton(root, MarketLensSprite.EXPAND_ICON, "Market Lens", "Expand",
			expandX, rowY + (TAB_ROW_HEIGHT - EXPAND_BUTTON_HEIGHT) / 2,
			EXPAND_BUTTON_WIDTH, EXPAND_BUTTON_HEIGHT, this::expand, () -> {});

		chartArea = geWidgets.chartPanel(root, chartX, CHART_TOP, w - chartX - PAD, h - CHART_TOP - PAD);
	}

	private void buildSummary(Widget root)
	{
		int x = PAD + 4;
		int w = SUMMARY_WIDTH - 4;

		widgets.text(root, "Buy price", FontID.PLAIN_11, Palette.ORANGE, WidgetTextAlignment.LEFT, x, CONTENT_TOP, w, 14);
		buyValue = widgets.text(root, "-", FontID.VERDANA_15, Palette.WHITE, WidgetTextAlignment.LEFT, x, CONTENT_TOP + 14, w, 20);
		buyAge = widgets.text(root, "", FontID.PLAIN_11, Palette.MUTED, WidgetTextAlignment.LEFT, x, CONTENT_TOP + 34, w, 14);

		widgets.text(root, "Sell price", FontID.PLAIN_11, Palette.ORANGE, WidgetTextAlignment.LEFT, x, CONTENT_TOP + 54, w, 14);
		sellValue = widgets.text(root, "-", FontID.VERDANA_15, Palette.WHITE, WidgetTextAlignment.LEFT, x, CONTENT_TOP + 68, w, 20);
		sellAge = widgets.text(root, "", FontID.PLAIN_11, Palette.MUTED, WidgetTextAlignment.LEFT, x, CONTENT_TOP + 88, w, 14);

		widgets.rect(root, Palette.DIVIDER, 0, true, x, CONTENT_TOP + 108, w, 1);

		int y = CONTENT_TOP + 114;
		marginValue = row(root, "Margin", x, y, w);
		taxValue = row(root, "GE tax", x, y += ROW_HEIGHT, w);
		profitValue = row(root, "Profit / item", x, y += ROW_HEIGHT, w);
		widgets.rect(root, Palette.DIVIDER, 0, true, x, y + ROW_HEIGHT + 3, w, 1);
		limitValue = row(root, "Buy limit", x, y += ROW_HEIGHT + 7, w);
		volumeValue = row(root, "Volume (1h)", x, y + ROW_HEIGHT, w);
	}

	private Widget row(Widget root, String label, int x, int y, int w)
	{
		widgets.text(root, label, FontID.PLAIN_11, Palette.ORANGE, WidgetTextAlignment.LEFT, x, y, w, ROW_HEIGHT);
		return widgets.text(root, "-", FontID.PLAIN_11, Palette.WHITE, WidgetTextAlignment.RIGHT, x, y, w, ROW_HEIGHT);
	}

	private void expand()
	{
		expandedWindow.open(this::selectTimeframe, this::selectChartType);
		refresh();
	}

	/** Switches line/candles in both windows and remembers the choice in the plugin config. */
	private void selectChartType(ChartType type)
	{
		state.setChartType(type);
		configManager.setConfiguration(MarketLensConfig.GROUP, MarketLensConfig.CHART_TYPE_KEY, type);
		refresh();
	}

	/** Switches the timeframe in both windows and stores it for the "Remember last timeframe" option. */
	private void selectTimeframe(Timeframe timeframe)
	{
		state.setTimeframe(timeframe);
		configManager.setConfiguration(MarketLensConfig.GROUP, MarketLensConfig.LAST_TIMEFRAME_KEY, timeframe);
		prices.refresh(state.getItemId(), timeframe);
		refresh();
	}
}

package com.marketlens.ui;

import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.SpritePixels;
import net.runelite.client.util.ImageUtil;

/**
 * Half-size item icons as custom sprites. Item graphics in widgets are always 36x32, so this renders
 * the item, scales it down and registers it under a sprite id of its own. Each item gets a different id,
 * so the client's widget sprite cache never holds a stale image and never has to be reset.
 * Only the most recent item's sprite is kept. Client thread only.
 */
@Singleton
public class SmallItemSprite
{
	/** Item sprites use ids below this; negative so they never collide with sprites from the game cache. */
	private static final int BASE_SPRITE_ID = -100_000;
	public static final int WIDTH = 18;
	public static final int HEIGHT = 16;

	private final Client client;
	private int spriteId = -1;

	@Inject
	SmallItemSprite(Client client)
	{
		this.client = client;
	}

	/** Returns the sprite id showing {@code itemId} at half size, creating it on first use. */
	public int spriteFor(int itemId)
	{
		int id = BASE_SPRITE_ID - itemId;
		if (id == spriteId)
		{
			return id;
		}

		SpritePixels item = client.createItemSprite(itemId, 1, 1, SpritePixels.DEFAULT_SHADOW_COLOR, 0, false,
			Constants.CLIENT_DEFAULT_ZOOM);
		if (item == null)
		{
			return -1;
		}

		BufferedImage small = ImageUtil.resizeImage(item.toBufferedImage(), WIDTH, HEIGHT);
		client.getSpriteOverrides().put(id, ImageUtil.getImageSpritePixels(small, client));
		clear();
		spriteId = id;
		return id;
	}

	public void clear()
	{
		client.getSpriteOverrides().remove(spriteId);
		spriteId = -1;
	}
}

package com.marketlens.ui;

import com.marketlens.price.Timeframe;
import java.awt.Dimension;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Consumer;
import net.runelite.api.FontID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;

/** A row of timeframe buttons on GE text-box sprites; the selected one is white. Client thread only. */
class TimeframeTabs
{
	private static final int TAB_WIDTH = 29;
	private static final int TAB_GAP = 2;
	private static final Dimension FALLBACK_CAP = new Dimension(4, 20);

	private final Map<Timeframe, Widget> labels = new EnumMap<>(Timeframe.class);
	private Timeframe selected;

	/** Builds the row with its top-left at x,y in {@code parent}. */
	TimeframeTabs(WidgetFactory widgets, Widget parent, int x, int y, Timeframe selected, Consumer<Timeframe> onSelect)
	{
		this.selected = selected;
		Dimension left = widgets.spriteSize(SpriteID.GeTextbackdrop.LEFT, FALLBACK_CAP);
		Dimension right = widgets.spriteSize(SpriteID.GeTextbackdrop.RIGHT, FALLBACK_CAP);
		int h = height(widgets);

		for (Timeframe timeframe : Timeframe.values())
		{
			widgets.sprite(parent, SpriteID.GeTextbackdrop.LEFT, x, y, left.width, h);
			widgets.tiledSprite(parent, SpriteID.GeTextbackdrop.MIDDLE, x + left.width, y, TAB_WIDTH - left.width - right.width, h);
			widgets.sprite(parent, SpriteID.GeTextbackdrop.RIGHT, x + TAB_WIDTH - right.width, y, right.width, h);

			Widget label = widgets.text(parent, timeframe.getLabel(), FontID.PLAIN_11, colour(timeframe),
				WidgetTextAlignment.CENTER, x, y, TAB_WIDTH, h);
			label.setName("<col=ff9040>" + timeframe.getLabel() + "</col>");
			label.setAction(0, "View");
			label.setHasListener(true);
			label.setOnOpListener((JavaScriptCallback) e -> onSelect.accept(timeframe));
			label.setOnMouseOverListener((JavaScriptCallback) e -> label.setTextColor(Palette.YELLOW));
			label.setOnMouseLeaveListener((JavaScriptCallback) e -> label.setTextColor(colour(timeframe)));
			labels.put(timeframe, label);

			x += TAB_WIDTH + TAB_GAP;
		}
	}

	static int height(WidgetFactory widgets)
	{
		return widgets.spriteSize(SpriteID.GeTextbackdrop.LEFT, FALLBACK_CAP).height;
	}

	/** The tab at canvas point x,y, or null. */
	Timeframe at(int x, int y)
	{
		for (Map.Entry<Timeframe, Widget> tab : labels.entrySet())
		{
			if (tab.getValue().getBounds().contains(x, y))
			{
				return tab.getKey();
			}
		}
		return null;
	}

	void select(Timeframe timeframe)
	{
		selected = timeframe;
		labels.forEach((tf, label) -> label.setTextColor(colour(tf)));
	}

	private int colour(Timeframe timeframe)
	{
		return timeframe == selected ? Palette.WHITE : Palette.ORANGE;
	}
}

package com.marketlens.ui;

import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;

/**
 * The window's title bar content: the small Market Lens icon and muted name on the left,
 * and the item icon and name centred. Client thread only.
 */
class TitleBar
{
	/** Vertical centre of the title text in the frame's title bar. */
	private static final int CENTER_Y = 18;
	private static final int ICON_GAP = 4;
	/** Left inset of the brand, where the GE shows its History button. */
	private static final int BRAND_LEFT = 12;

	private final Widget title;
	private final Widget itemIcon;

	/** @param title the frame's title text, from {@link GeWidgets#frame} */
	TitleBar(WidgetFactory widgets, Widget parent, Widget title)
	{
		this.title = title;
		itemIcon = widgets.sprite(parent, -1, 0, CENTER_Y - SmallItemSprite.HEIGHT / 2,
			SmallItemSprite.WIDTH, SmallItemSprite.HEIGHT);

		MarketLensSprite brand = MarketLensSprite.CHART_ICON_SMALL;
		widgets.sprite(parent, brand.getSpriteId(), BRAND_LEFT, CENTER_Y - brand.getHeight() / 2,
			brand.getWidth(), brand.getHeight());
		widgets.text(parent, "Market Lens", FontID.PLAIN_11, Palette.MUTED, WidgetTextAlignment.LEFT,
			BRAND_LEFT + brand.getWidth() + ICON_GAP, 6, 120, 24);
	}

	/** Shows the item name centred, with its icon just left of the text. */
	void show(String itemName, int itemSpriteId)
	{
		title.setText(itemName);
		FontTypeFace font = title.getFont();
		int textWidth = font != null ? font.getTextWidth(itemName) : itemName.length() * 8;
		int centerX = title.getOriginalX() + title.getOriginalWidth() / 2;
		itemIcon.setSpriteId(itemSpriteId);
		itemIcon.setOriginalX(centerX - textWidth / 2 - ICON_GAP - SmallItemSprite.WIDTH);
		itemIcon.revalidate();
	}
}

package com.marketlens.ui;

import java.awt.Dimension;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/** Primitive builders for dynamic widgets. Client thread only. */
@Singleton
public class WidgetFactory
{
	private final Client client;

	@Inject
	WidgetFactory(Client client)
	{
		this.client = client;
	}

	/** Native size of a cache sprite, or {@code fallback} if it is not loaded. */
	public Dimension spriteSize(int spriteId, Dimension fallback)
	{
		SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), spriteId, 0);
		if (sprites == null || sprites.length == 0 || sprites[0] == null)
		{
			return fallback;
		}
		return new Dimension(sprites[0].getMaxWidth(), sprites[0].getMaxHeight());
	}

	public Widget layer(Widget parent, int x, int y, int w, int h)
	{
		return place(parent.createChild(WidgetType.LAYER), x, y, w, h);
	}

	public Widget sprite(Widget parent, int spriteId, int x, int y, int w, int h)
	{
		Widget widget = place(parent.createChild(WidgetType.GRAPHIC), x, y, w, h);
		widget.setSpriteId(spriteId);
		return widget;
	}

	public Widget tiledSprite(Widget parent, int spriteId, int x, int y, int w, int h)
	{
		Widget widget = sprite(parent, spriteId, x, y, w, h);
		widget.setSpriteTiling(true);
		return widget;
	}

	public Widget rect(Widget parent, int color, int opacity, boolean filled, int x, int y, int w, int h)
	{
		Widget widget = place(parent.createChild(WidgetType.RECTANGLE), x, y, w, h);
		widget.setTextColor(color);
		widget.setOpacity(opacity);
		widget.setFilled(filled);
		return widget;
	}

	public Widget text(Widget parent, String text, int fontId, int color, int xAlign, int x, int y, int w, int h)
	{
		Widget widget = place(parent.createChild(WidgetType.TEXT), x, y, w, h);
		widget.setText(text);
		widget.setFontId(fontId);
		widget.setTextColor(color);
		widget.setTextShadowed(true);
		widget.setXTextAlignment(xAlign);
		widget.setYTextAlignment(WidgetTextAlignment.CENTER);
		return widget;
	}

	/** Positions a new widget relative to its parent. Parents must be placed before their children. */
	private static Widget place(Widget widget, int x, int y, int w, int h)
	{
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setOriginalWidth(w);
		widget.setOriginalHeight(h);
		widget.revalidate();
		return widget;
	}
}

