package com.marketlens.chart;

import static org.junit.Assert.assertEquals;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class AxisTicksTest
{
	private static final ZoneId UTC = ZoneOffset.UTC;

	@Test
	public void priceTicksAreRound()
	{
		assertEquals(Arrays.asList(805_000.0, 810_000.0, 815_000.0, 820_000.0, 825_000.0),
			AxisTicks.prices(801_554, 828_861, 5));
	}

	@Test
	public void priceTicksUseQuarterStepsWhenTheyFitBetter()
	{
		assertEquals(Arrays.asList(1_250.0, 1_500.0, 1_750.0, 2_000.0, 2_250.0, 2_500.0),
			AxisTicks.prices(1_034, 2_620, 6));
	}

	@Test
	public void priceTicksNeverStepBelowOneCoin()
	{
		List<Double> ticks = AxisTicks.prices(10, 12, 10);
		assertEquals(Arrays.asList(10.0, 11.0, 12.0), ticks);
	}

	@Test
	public void timeStepPicksSmallestFittingStep()
	{
		assertEquals(3 * 3600, AxisTicks.timeStep(0, 86_400, 8));
		assertEquals(15 * 60, AxisTicks.timeStep(0, 3_600, 5));
	}

	@Test
	public void timeTicksAlignToWallClock()
	{
		// 00:10 .. 03:20 UTC, hourly ticks land on the hour
		assertEquals(Arrays.asList(3_600L, 7_200L, 10_800L), AxisTicks.times(600, 12_000, 3_600, UTC));
	}

	@Test
	public void timeLabels()
	{
		assertEquals("01:00", AxisTicks.timeLabel(3_600, 3_600, UTC, false));
		assertEquals("2 Jan", AxisTicks.timeLabel(86_400, 3_600, UTC, false));
		assertEquals("2 Jan", AxisTicks.timeLabel(86_400, 86_400, UTC, false));
		assertEquals("Jan '70", AxisTicks.timeLabel(86_400, 30 * 86_400, UTC, false));
	}

	@Test
	public void twelveHourLabels()
	{
		assertEquals("1:00 PM", AxisTicks.timeLabel(13 * 3_600, 3_600, UTC, true));
		assertEquals("2 Jan", AxisTicks.timeLabel(86_400, 3_600, UTC, true));
		assertEquals("Thu 1 Jan 1:00 PM", AxisTicks.crosshairLabel(13 * 3_600, 300, UTC, true));
		assertEquals("Thu 1 Jan 13:00", AxisTicks.crosshairLabel(13 * 3_600, 300, UTC, false));
	}
}

package com.marketlens.chart;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.marketlens.price.TimeseriesPoint;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class CandlesTest
{
	private static final double EPS = 1e-9;

	private static TimeseriesPoint point(long t, Double buy, Double sell)
	{
		return new TimeseriesPoint(t, buy, sell, 1L, 2L);
	}

	@Test
	public void candleSpansHighestBuyToLowestSellAndClosesAtLastMidpoint()
	{
		List<Candle> candles = Candles.build(Arrays.asList(
			point(0, 104.0, 100.0),     // mid 102: opens the first candle
			point(300, 110.0, 101.0),
			point(600, 107.0, 98.0)),   // mid 102.5: closes it
			900);

		assertEquals(1, candles.size());
		Candle c = candles.get(0);
		assertEquals(102.0, c.getOpen(), EPS);
		assertEquals(110.0, c.getHigh(), EPS);
		assertEquals(98.0, c.getLow(), EPS);
		assertEquals(102.5, c.getClose(), EPS);
		assertEquals(Long.valueOf(3), c.getBuyVolume());
		assertEquals(Long.valueOf(6), c.getSellVolume());
		assertTrue(c.isUp());
	}

	@Test
	public void nextCandleOpensAtThePreviousClose()
	{
		List<Candle> candles = Candles.build(Arrays.asList(
			point(0, 104.0, 100.0),
			point(300, 100.0, 96.0)), 300);

		assertEquals(2, candles.size());
		assertEquals(102.0, candles.get(1).getOpen(), EPS);
		assertEquals(98.0, candles.get(1).getClose(), EPS);
		assertFalse(candles.get(1).isUp());
	}

	@Test
	public void wicksAlwaysIncludeOpenAndClose()
	{
		// Only a sell price in the second bucket: its mid (90) is below its own range of buys (none)
		List<Candle> candles = Candles.build(Arrays.asList(
			point(0, 104.0, 100.0),
			point(300, null, 90.0)), 300);

		Candle second = candles.get(1);
		assertEquals(102.0, second.getHigh(), EPS);
		assertEquals(90.0, second.getLow(), EPS);
	}

	@Test
	public void bucketsWithoutTradesAreSkipped()
	{
		List<Candle> candles = Candles.build(Arrays.asList(
			point(0, 104.0, 100.0),
			point(300, null, null),
			point(600, 106.0, 102.0)), 300);

		assertEquals(2, candles.size());
		assertEquals(600, candles.get(1).getTimestamp());
		assertEquals(102.0, candles.get(1).getOpen(), EPS);
	}
}

package com.marketlens.chart;

import static org.junit.Assert.assertEquals;
import com.marketlens.price.TimeseriesPoint;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class ChartScaleTest
{
	private static final Rectangle PLOT = new Rectangle(0, 0, 1000, 500);
	private static final double EPS = 1e-6;

	/** Points every 100s from t=0, with high = 100 + i and low = 90 + i. */
	private static List<TimeseriesPoint> series(int count)
	{
		List<TimeseriesPoint> points = new ArrayList<>();
		for (int i = 0; i < count; i++)
		{
			points.add(new TimeseriesPoint(i * 100L, 100.0 + i, 90.0 + i, 1L, 1L));
		}
		return points;
	}

	@Test
	public void visibleSliceKeepsOnePointOfSlackEachSide()
	{
		ChartScale scale = new ChartScale(series(10), 250, 550, 100, PLOT, true);
		assertEquals(2, scale.getFirst());
		assertEquals(6, scale.getLast());
	}

	@Test
	public void priceRangeIsPaddedByEightPercent()
	{
		// Visible points 2..6: lows from 92, highs up to 106 -> range 14, padding 1.12
		ChartScale scale = new ChartScale(series(10), 250, 550, 100, PLOT, true);
		assertEquals(92 - 1.12, scale.getMin(), EPS);
		assertEquals(106 + 1.12, scale.getMax(), EPS);
	}

	@Test
	public void livePricesAreFittedOnlyWhenTheNewestPointIsVisible()
	{
		ChartScale atEnd = new ChartScale(series(10), 500, 900, 100, PLOT, true, 150.0, null);
		assertEquals(150.0, atEnd.getMax() - (150 - 94) * 0.08, EPS);

		ChartScale inPast = new ChartScale(series(10), 0, 300, 100, PLOT, true, 150.0, null);
		assertEquals(104 + 14 * 0.08, inPast.getMax(), EPS);
	}

	@Test
	public void pixelMappingRoundTrips()
	{
		ChartScale scale = new ChartScale(series(10), 0, 900, 100, PLOT, true);
		assertEquals(0, scale.x(0));
		assertEquals(1000, scale.x(900));
		assertEquals(450, scale.timeAt(scale.x(450)), 1);
		assertEquals(100, scale.priceAt(scale.y(100)), 0.5);
	}

	@Test
	public void nearestPicksTheClosestVisiblePoint()
	{
		ChartScale scale = new ChartScale(series(10), 0, 900, 100, PLOT, true);
		assertEquals(3, scale.nearestIndex(340));
		assertEquals(4, scale.nearestIndex(360));
	}
}

package com.marketlens.chart;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class ChartViewportTest
{
	private static final double EPS = 1e-6;

	@Test
	public void resetShowsFullRangeByDefault()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 1000, 50, 0);
		assertEquals(0, v.getStart(), EPS);
		assertEquals(1000, v.getEnd(), EPS);
	}

	@Test
	public void resetHonoursInitialWindowAnchoredToEnd()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 21_600, 900, 3_600);
		assertEquals(18_000, v.getStart(), EPS);
		assertEquals(21_600, v.getEnd(), EPS);
	}

	@Test
	public void zoomKeepsAnchorFixed()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 1000, 10, 0);
		v.zoom(0.5, 250);
		// anchor was at 25% of the window and stays there
		assertEquals(125, v.getStart(), EPS);
		assertEquals(625, v.getEnd(), EPS);
	}

	@Test
	public void zoomIsClampedToMinSpanAndDataRange()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 1000, 100, 0);
		v.zoom(0.01, 500);
		assertEquals(100, v.getEnd() - v.getStart(), EPS);
		v.zoom(1000, 500);
		assertEquals(0, v.getStart(), EPS);
		assertEquals(1000, v.getEnd(), EPS);
	}

	@Test
	public void updateRangeFollowsNewestDataAndKeepsZoom()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 1000, 10, 200);
		v.updateRange(100, 1300);
		assertEquals(1100, v.getStart(), EPS);
		assertEquals(1300, v.getEnd(), EPS);
	}

	@Test
	public void updateRangeLeavesPannedViewInPlace()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 1000, 10, 200);
		v.pan(-300);
		v.updateRange(100, 1300);
		assertEquals(500, v.getStart(), EPS);
		assertEquals(700, v.getEnd(), EPS);
	}

	@Test
	public void panStopsAtDataEdges()
	{
		ChartViewport v = new ChartViewport();
		v.setData(0, 1000, 10, 200);
		v.pan(500);
		assertEquals(800, v.getStart(), EPS);
		v.pan(-5000);
		assertEquals(0, v.getStart(), EPS);
		assertEquals(200, v.getEnd(), EPS);
	}
}

package com.marketlens.chart;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.marketlens.price.TimeseriesPoint;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class DownsampleTest
{
	private static final double EPS = 1e-9;

	@Test
	public void keepsRawBucketsWhenTheyAreFarEnoughApart()
	{
		// 5-minute buckets at 60 seconds per pixel are 5 px apart
		assertEquals(300, Downsample.interval(300, 60, 3));
	}

	@Test
	public void picksTheSmallestNiceIntervalThatFits()
	{
		// 24h of 5-minute buckets in ~370 px: 233 s/px; 15 min = 3.9 px
		assertEquals(900, Downsample.interval(300, 86_400.0 / 370, 3));
		// a week of hourly buckets in ~370 px: 2 hours = 4.4 px
		assertEquals(7_200, Downsample.interval(3_600, 7 * 86_400.0 / 370, 3));
		// a year of daily buckets in ~370 px: 3 days = 3 px
		assertEquals(3 * 86_400, Downsample.interval(86_400, 365 * 86_400.0 / 370, 3));
	}

	@Test
	public void onlyUsesWholeMultiplesOfTheBucket()
	{
		// 6-hour buckets 1 px apart: 12 hours (2 px) is too dense, so 1 day (4 px); never e.g. 3 hours
		assertEquals(86_400, Downsample.interval(21_600, 21_600, 3));
	}

	@Test
	public void mergedPriceIsTheVolumeWeightedAverage()
	{
		List<TimeseriesPoint> merged = Downsample.merge(Arrays.asList(
			new TimeseriesPoint(0, 100.0, 90.0, 10L, 1L),
			new TimeseriesPoint(300, 104.0, 94.0, 30L, 3L)), 900);

		assertEquals(1, merged.size());
		TimeseriesPoint p = merged.get(0);
		assertEquals("10 trades at 100 and 30 at 104", 103.0, p.getAvgHighPrice(), EPS);
		assertEquals(93.0, p.getAvgLowPrice(), EPS);
		assertEquals(Long.valueOf(40), p.getHighPriceVolume());
		assertEquals(Long.valueOf(4), p.getLowPriceVolume());
	}

	@Test
	public void bucketsWithoutTradesDontCount()
	{
		List<TimeseriesPoint> merged = Downsample.merge(Arrays.asList(
			new TimeseriesPoint(0, null, 90.0, 0L, 2L),
			new TimeseriesPoint(300, 104.0, null, 5L, 0L),
			new TimeseriesPoint(600, null, null, 0L, 0L)), 900);

		TimeseriesPoint p = merged.get(0);
		assertEquals(104.0, p.getAvgHighPrice(), EPS);
		assertEquals(90.0, p.getAvgLowPrice(), EPS);
		assertEquals(Long.valueOf(5), p.getHighPriceVolume());
	}

	@Test
	public void sideWithNoPricesStaysEmpty()
	{
		List<TimeseriesPoint> merged = Downsample.merge(Arrays.asList(
			new TimeseriesPoint(0, null, 90.0, null, 2L),
			new TimeseriesPoint(300, null, 91.0, null, 2L)), 900);

		assertNull(merged.get(0).getAvgHighPrice());
		assertNull(merged.get(0).getHighPriceVolume());
	}

	@Test
	public void groupsAlignToClockBoundaries()
	{
		// Buckets at 10:45, 10:50 | 11:00, 11:05 with 15-minute groups -> starts 10:45 and 11:00
		long t = 10 * 3600 + 45 * 60;
		List<TimeseriesPoint> merged = Downsample.merge(Arrays.asList(
			new TimeseriesPoint(t, 1.0, 1.0, 1L, 1L),
			new TimeseriesPoint(t + 300, 1.0, 1.0, 1L, 1L),
			new TimeseriesPoint(t + 900, 1.0, 1.0, 1L, 1L),
			new TimeseriesPoint(t + 1200, 1.0, 1.0, 1L, 1L)), 900);

		assertEquals(2, merged.size());
		assertEquals(t, merged.get(0).getTimestamp());
		assertEquals(t + 900, merged.get(1).getTimestamp());
	}
}

